{"command":"cd /workspace && cat > src/peg.rs <<'EOF'
// A small PEG engine emulating the semantics (including error reporting)
// of a classic PEG parser generator with implicit whitespace handling.

use std::collections::HashMap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum RuleType {
    Normal,
    Silent,
    Atomic,
    CompoundAtomic,
    NonAtomic,
}

#[derive(Clone, Debug)]
pub enum Expr {
    Str(String),
    Range(char, char),
    Ident(String),
    Rule(usize),
    Seq(Vec<Expr>),
    Choice(Vec<Expr>),
    Opt(Box<Expr>),
    Rep(Box<Expr>),
    RepOnce(Box<Expr>),
    PosPred(Box<Expr>),
    NegPred(Box<Expr>),
    Push(Box<Expr>),
    Pop,
    Peek,
    Drop,
    Any,
    Soi,
    EoiPrim,
}

pub struct Rule {
    pub name: String,
    pub ty: RuleType,
    pub expr: Expr,
}

pub struct Grammar {
    pub rules: Vec<Rule>,
    pub index: HashMap<String, usize>,
    ws: Option<usize>,
    comment: Option<usize>,
}

#[derive(Clone, Debug)]
pub struct Pair {
    pub rule: usize,
    pub start: usize,
    pub end: usize,
    pub children: Vec<Pair>,
}

pub struct ParseError {
    pub pos: usize,
    pub positives: Vec<usize>,
    pub negatives: Vec<usize>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Atom {
    Atomic,
    Compound,
    NonAtomic,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Look {
    None,
    Positive,
    Negative,
}

enum Tok {
    Start { end: usize, pos: usize },
    End { start: usize, rule: usize, pos: usize },
}

// ---------------------------------------------------------------------------
// Grammar text parser (pest-like syntax)
// ---------------------------------------------------------------------------

struct GP<'a> {
    s: &'a [u8],
    p: usize,
}

impl<'a> GP<'a> {
    fn ws(&mut self) {
        loop {
            while self.p < self.s.len() && (self.s[self.p] as char).is_whitespace() {
                self.p += 1;
            }
            if self.p + 1 < self.s.len() && self.s[self.p] == b'/' && self.s[self.p + 1] == b'/' {
                while self.p < self.s.len() && self.s[self.p] != b'\n' {
                    self.p += 1;
                }
                continue;
            }
            break;
        }
    }
    fn peek(&mut self) -> Option<u8> {
        self.ws();
        self.s.get(self.p).copied()
    }
    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) {
            self.p += 1;
            true
        } else {
            false
        }
    }
    fn ident(&mut self) -> String {
        self.ws();
        let st = self.p;
        while self.p < self.s.len() && ((self.s[self.p] as char).is_ascii_alphanumeric() || self.s[self.p] == b'_') {
            self.p += 1;
        }
        String::from_utf8(self.s[st..self.p].to_vec()).unwrap()
    }
    fn string(&mut self, q: u8) -> String {
        // assumes current char is quote
        self.p += 1;
        let mut out = String::new();
        let mut bytes = Vec::new();
        loop {
            let c = self.s[self.p];
            if c == q {
                self.p += 1;
                break;
            }
            if c == b'\\' {
                let n = self.s[self.p + 1];
                self.p += 2;
                match n {
                    b'n' => bytes.push(b'\n'),
                    b't' => bytes.push(b'\t'),
                    b'r' => bytes.push(b'\r'),
                    b'\\' => bytes.push(b'\\'),
                    b'"' => bytes.push(b'"'),
                    b'\'' => bytes.push(b'\''),
                    b'0' => bytes.push(0),
                    _ => panic!("bad escape"),
                }
                continue;
            }
            bytes.push(c);
            self.p += 1;
        }
        out.push_str(&String::from_utf8(bytes).unwrap());
        out
    }
    fn expr(&mut self) -> Expr {
        let mut alts = vec![self.seq()];
        while self.eat(b'|') {
            alts.push(self.seq());
        }
        if alts.len() == 1 {
            alts.pop().unwrap()
        } else {
            Expr::Choice(alts)
        }
    }
    fn seq(&mut self) -> Expr {
        let mut items = vec![self.term()];
        while self.eat(b'~') {
            items.push(self.term());
        }
        if items.len() == 1 {
            items.pop().unwrap()
        } else {
            Expr::Seq(items)
        }
    }
    fn term(&mut self) -> Expr {
        if self.eat(b'&') {
            return Expr::PosPred(Box::new(self.term()));
        }
        if self.eat(b'!') {
            return Expr::NegPred(Box::new(self.term()));
        }
        let mut e = self.primary();
        loop {
            if self.eat(b'?') {
                e = Expr::Opt(Box::new(e));
            } else if self.eat(b'*') {
                e = Expr::Rep(Box::new(e));
            } else if self.eat(b'+') {
                e = Expr::RepOnce(Box::new(e));
            } else {
                break;
            }
        }
        e
    }
    fn primary(&mut self) -> Expr {
        match self.peek() {
            Some(b'(') => {
                self.p += 1;
                let e = self.expr();
                assert!(self.eat(b')'));
                e
            }
            Some(b'"') => Expr::Str(self.string(b'"')),
            Some(b'\'') => {
                let a = self.string(b'\'');
                if self.peek() == Some(b'.') {
                    self.p += 2; // ..
                    self.ws();
                    let b = self.string(b'\'');
                    Expr::Range(a.chars().next().unwrap(), b.chars().next().unwrap())
                } else {
                    Expr::Str(a)
                }
            }
            _ => {
                let id = self.ident();
                match id.as_str() {
                    "ANY" => Expr::Any,
                    "SOI" => Expr::Soi,
                    "POP" => Expr::Pop,
                    "PEEK" => Expr::Peek,
                    "DROP" => Expr::Drop,
                    "ASCII_DIGIT" => Expr::Range('0', '9'),
                    "ASCII_ALPHA" => Expr::Choice(vec![Expr::Range('a', 'z'), Expr::Range('A', 'Z')]),
                    "ASCII_ALPHANUMERIC" => Expr::Choice(vec![
                        Expr::Range('a', 'z'),
                        Expr::Range('A', 'Z'),
                        Expr::Range('0', '9'),
                    ]),
                    "PUSH" => {
                        assert!(self.eat(b'('));
                        let e = self.expr();
                        assert!(self.eat(b')'));
                        Expr::Push(Box::new(e))
                    }
                    "" => panic!("grammar parse error at {}", self.p),
                    _ => Expr::Ident(id),
                }
            }
        }
    }
}

fn resolve(e: &mut Expr, idx: &HashMap<String, usize>) {
    match e {
        Expr::Ident(name) => {
            let id = *idx.get(name.as_str()).unwrap_or_else(|| panic!("unknown rule {}", name));
            *e = Expr::Rule(id);
        }
        Expr::Seq(v) | Expr::Choice(v) => {
            for x in v.iter_mut() {
                resolve(x, idx);
            }
        }
        Expr::Opt(b) | Expr::Rep(b) | Expr::RepOnce(b) | Expr::PosPred(b) | Expr::NegPred(b) | Expr::Push(b) => {
            resolve(b, idx)
        }
        _ => {}
    }
}

impl Grammar {
    pub fn new(text: &str) -> Grammar {
        let mut gp = GP { s: text.as_bytes(), p: 0 };
        let mut rules = vec![Rule { name: "EOI".to_string(), ty: RuleType::Normal, expr: Expr::EoiPrim }];
        loop {
            gp.ws();
            if gp.p >= gp.s.len() {
                break;
            }
            let name = gp.ident();
            assert!(gp.eat(b'='), "expected = after {}", name);
            let ty = match gp.peek() {
                Some(b'_') => {
                    gp.p += 1;
                    RuleType::Silent
                }
                Some(b'@') => {
                    gp.p += 1;
                    RuleType::Atomic
                }
                Some(b'$') => {
                    gp.p += 1;
                    RuleType::CompoundAtomic
                }
                Some(b'!') => {
                    gp.p += 1;
                    RuleType::NonAtomic
                }
                _ => RuleType::Normal,
            };
            assert!(gp.eat(b'{'), "expected {{ in {}", name);
            let expr = gp.expr();
            assert!(gp.eat(b'}'), "expected }} in {}", name);
            rules.push(Rule { name, ty, expr });
        }
        let mut index = HashMap::new();
        for (i, r) in rules.iter().enumerate() {
            index.insert(r.name.clone(), i);
        }
        for r in rules.iter_mut() {
            resolve(&mut r.expr, &index);
        }
        let ws = index.get("WHITESPACE").copied();
        let comment = index.get("COMMENT").copied();
        Grammar { rules, index, ws, comment }
    }

    pub fn id(&self, name: &str) -> usize {
        self.index[name]
    }

    pub fn name(&self, id: usize) -> &str {
        &self.rules[id].name
    }

    /// Parse `input` starting with rule `start`. The start rule itself is
    /// invoked without tracking (it never shows up in error messages).
    pub fn parse(&self, start: usize, input: &str) -> Result<Vec<Pair>, ParseError> {
        let mut st = State {
            g: self,
            input,
            bytes: input.as_bytes(),
            pos: 0,
            atom: Atom::NonAtomic,
            look: Look::None,
            attempt_pos: 0,
            pos_att: Vec::new(),
            neg_att: Vec::new(),
            stack: Vec::new(),
            queue: Vec::new(),
        };
        let ok = st.rule_untracked(start);
        if ok {
            Ok(build_pairs(&st.queue))
        } else {
            let mut p = st.pos_att.clone();
            p.sort();
            p.dedup();
            let mut n = st.neg_att.clone();
            n.sort();
            n.dedup();
            Err(ParseError { pos: st.attempt_pos, positives: p, negatives: n })
        }
    }
}

fn build_pairs(queue: &[Tok]) -> Vec<Pair> {
    fn build(queue: &[Tok], i: &mut usize, end: usize) -> Vec<Pair> {
        let mut out = Vec::new();
        while *i < end {
            match queue[*i] {
                Tok::Start { end: e, pos } => {
                    let start_idx = *i;
                    *i += 1;
                    let children = build(queue, i, e);
                    // queue[e] is End
                    let (rule, epos) = match queue[e] {
                        Tok::End { rule, pos, start } => {
                            debug_assert_eq!(start, start_idx);
                            (rule, pos)
                        }
                        _ => unreachable!(),
                    };
                    *i = e + 1;
                    out.push(Pair { rule, start: pos, end: epos, children });
                }
                Tok::End { .. } => {
                    *i += 1;
                }
            }
        }
        out
    }
    let mut i = 0;
    build(queue, &mut i, queue.len())
}

struct State<'a> {
    g: &'a Grammar,
    input: &'a str,
    bytes: &'a [u8],
    pos: usize,
    atom: Atom,
    look: Look,
    attempt_pos: usize,
    pos_att: Vec<usize>,
    neg_att: Vec<usize>,
    stack: Vec<(usize, usize)>,
    queue: Vec<Tok>,
}

impl<'a> State<'a> {
    fn attempts_at(&self, pos: usize) -> usize {
        if self.attempt_pos == pos {
            self.pos_att.len() + self.neg_att.len()
        } else {
            0
        }
    }

    fn track(&mut self, rule: usize, pos: usize, pai: usize, nai: usize, prev: usize) {
        if self.atom == Atom::Atomic {
            return;
        }
        let curr = self.attempts_at(pos);
        if curr > prev && curr - prev == 1 {
            return;
        }
        if pos == self.attempt_pos {
            self.pos_att.truncate(pai);
            self.neg_att.truncate(nai);
        }
        if pos > self.attempt_pos {
            self.pos_att.clear();
            self.neg_att.clear();
            self.attempt_pos = pos;
        }
        if pos == self.attempt_pos {
            if self.look != Look::Negative {
                self.pos_att.push(rule);
            } else {
                self.neg_att.push(rule);
            }
        }
    }

    fn with_atom(&mut self, a: Atom, id: usize) -> bool {
        let init = self.atom;
        self.atom = a;
        let r = self.eval_rule_body(id);
        self.atom = init;
        r
    }

    fn eval_rule_body(&mut self, id: usize) -> bool {
        let g = self.g;
        let e: &Expr = &g.rules[id].expr;
        self.eval(e)
    }

    fn rule_untracked(&mut self, id: usize) -> bool {
        // like rule() but without error tracking
        let actual_pos = self.pos;
        let index = self.queue.len();
        self.queue.push(Tok::Start { end: 0, pos: actual_pos });
        let ok = self.eval_rule_body(id);
        if ok {
            let new_index = self.queue.len();
            if let Tok::Start { ref mut end, .. } = self.queue[index] {
                *end = new_index;
            }
            self.queue.push(Tok::End { start: index, rule: id, pos: self.pos });
        } else {
            self.queue.truncate(index);
        }
        ok
    }

    fn rule(&mut self, id: usize) -> bool {
        let g = self.g;
        let ty = g.rules[id].ty;
        if Some(id) == g.ws || Some(id) == g.comment {
            let init = self.atom;
            self.atom = Atom::Atomic;
            let r = self.eval_rule_body(id);
            self.atom = init;
            if ty == RuleType::Silent {
                return r;
            }
        }
        if ty == RuleType::Silent {
            return self.eval_rule_body(id);
        }
        let actual_pos = self.pos;
        let index = self.queue.len();
        let (pai, nai) = if actual_pos == self.attempt_pos {
            (self.pos_att.len(), self.neg_att.len())
        } else {
            (0, 0)
        };
        let push_tok = self.look == Look::None && self.atom != Atom::Atomic;
        if push_tok {
            self.queue.push(Tok::Start { end: 0, pos: actual_pos });
        }
        let attempts = self.attempts_at(actual_pos);
        let ok = match ty {
            RuleType::Atomic => self.with_atom(Atom::Atomic, id),
            RuleType::CompoundAtomic => self.with_atom(Atom::Compound, id),
            RuleType::NonAtomic => self.with_atom(Atom::NonAtomic, id),
            _ => self.eval_rule_body(id),
        };
        if ok {
            if self.look == Look::Negative {
                self.track(id, actual_pos, pai, nai, attempts);
            }
            if push_tok {
                let new_index = self.queue.len();
                if let Tok::Start { ref mut end, .. } = self.queue[index] {
                    *end = new_index;
                }
                self.queue.push(Tok::End { start: index, rule: id, pos: self.pos });
            }
        } else {
            if self.look != Look::Negative {
                self.track(id, actual_pos, pai, nai, attempts);
            }
            if push_tok {
                self.queue.truncate(index);
            }
        }
        ok
    }

    fn skip(&mut self) {
        if self.atom != Atom::NonAtomic {
            return;
        }
        let ws = self.g.ws;
        let cm = self.g.comment;
        if let Some(w) = ws {
            while self.rule(w) {}
        }
        if let Some(c) = cm {
            loop {
                let save = self.pos;
                let qlen = self.queue.len();
                if !self.rule(c) {
                    self.pos = save;
                    self.queue.truncate(qlen);
                    break;
                }
                if let Some(w) = ws {
                    while self.rule(w) {}
                }
            }
        }
    }

    fn next_char(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn eval(&mut self, e: &Expr) -> bool {
        match e {
            Expr::Str(s) => {
                if self.bytes[self.pos..].starts_with(s.as_bytes()) {
                    self.pos += s.len();
                    true
                } else {
                    false
                }
            }
            Expr::Range(a, b) => match self.next_char() {
                Some(c) if c >= *a && c <= *b => {
                    self.pos += c.len_utf8();
                    true
                }
                _ => false,
            },
            Expr::Any => match self.next_char() {
                Some(c) => {
                    self.pos += c.len_utf8();
                    true
                }
                None => false,
            },
            Expr::Soi => self.pos == 0,
            Expr::EoiPrim => self.pos == self.bytes.len(),
            Expr::Rule(id) => self.rule(*id),
            Expr::Ident(_) => unreachable!(),
            Expr::Seq(items) => {
                let save_pos = self.pos;
                let qlen = self.queue.len();
                let stack = self.stack.clone();
                for (i, it) in items.iter().enumerate() {
                    if i > 0 {
                        self.skip();
                    }
                    if !self.eval(it) {
                        self.pos = save_pos;
                        self.queue.truncate(qlen);
                        self.stack = stack;
                        return false;
                    }
                }
                true
            }
            Expr::Choice(alts) => {
                for a in alts {
                    let stack = self.stack.clone();
                    let save_pos = self.pos;
                    let qlen = self.queue.len();
                    if self.eval(a) {
                        return true;
                    }
                    self.stack = stack;
                    self.pos = save_pos;
                    self.queue.truncate(qlen);
                }
                false
            }
            Expr::Opt(b) => {
                let stack = self.stack.clone();
                let save_pos = self.pos;
                let qlen = self.queue.len();
                if !self.eval(b) {
                    self.stack = stack;
                    self.pos = save_pos;
                    self.queue.truncate(qlen);
                }
                true
            }
            Expr::Rep(b) => {
                {
                    let stack = self.stack.clone();
                    let save_pos = self.pos;
                    let qlen = self.queue.len();
                    if !self.eval(b) {
                        self.stack = stack;
                        self.pos = save_pos;
                        self.queue.truncate(qlen);
                        return true;
                    }
                }
                self.rep_tail(b);
                true
            }
            Expr::RepOnce(b) => {
                if !self.eval(b) {
                    return false;
                }
                self.rep_tail(b);
                true
            }
            Expr::PosPred(b) | Expr::NegPred(b) => {
                let positive = matches!(e, Expr::PosPred(_));
                let init_look = self.look;
                self.look = if positive {
                    match init_look {
                        Look::None | Look::Positive => Look::Positive,
                        Look::Negative => Look::Negative,
                    }
                } else {
                    match init_look {
                        Look::None | Look::Positive => Look::Negative,
                        Look::Negative => Look::Positive,
                    }
                };
                let save_pos = self.pos;
                let stack = self.stack.clone();
                let qlen = self.queue.len();
                let r = self.eval(b);
                self.pos = save_pos;
                self.stack = stack;
                self.queue.truncate(qlen);
                self.look = init_look;
                if positive {
                    r
                } else {
                    !r
                }
            }
            Expr::Push(b) => {
                let start = self.pos;
                if self.eval(b) {
                    self.stack.push((start, self.pos));
                    true
                } else {
                    false
                }
            }
            Expr::Pop => match self.stack.last().copied() {
                Some((s, en)) => {
                    let lit = &self.bytes[s..en];
                    if self.bytes[self.pos..].starts_with(lit) {
                        self.pos += en - s;
                        self.stack.pop();
                        true
                    } else {
                        false
                    }
                }
                None => false,
            },
            Expr::Peek => match self.stack.last().copied() {
                Some((s, en)) => {
                    let lit = &self.bytes[s..en];
                    if self.bytes[self.pos..].starts_with(lit) {
                        self.pos += en - s;
                        true
                    } else {
                        false
                    }
                }
                None => false,
            },
            Expr::Drop => {
                if self.stack.pop().is_some() {
                    true
                } else {
                    false
                }
            }
        }
    }

    fn rep_tail(&mut self, b: &Expr) {
        loop {
            let stack = self.stack.clone();
            let save_pos = self.pos;
            let qlen = self.queue.len();
            self.skip();
            if !self.eval(b) {
                self.stack = stack;
                self.pos = save_pos;
                self.queue.truncate(qlen);
                break;
            }
            if self.pos == save_pos {
                // no progress: avoid infinite loop
                break;
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Error formatting
// ---------------------------------------------------------------------------

fn enumerate(names: &[&str]) -> String {
    match names.len() {
        1 => names[0].to_string(),
        2 => format!("{} or {}", names[0], names[1]),
        l => {
            let sep = names[..l - 1].join(", ");
            format!("{}, or {}", sep, names[l - 1])
        }
    }
}

pub fn line_col(input: &str, pos: usize) -> (usize, usize) {
    let mut p = pos;
    let slice = &input[..pos];
    let mut chars = slice.chars().peekable();
    let mut lc = (1usize, 1usize);
    while p != 0 {
        match chars.next() {
            Some('\r') => {
                if let Some(&'\n') = chars.peek() {
                    chars.next();
                    if p == 1 {
                        p -= 1;
                    } else {
                        p -= 2;
                    }
                    lc = (lc.0 + 1, 1);
                } else {
                    p -= 1;
                    lc = (lc.0, lc.1 + 1);
                }
            }
            Some('\n') => {
                p -= 1;
                lc = (lc.0 + 1, 1);
            }
            Some(c) => {
                p -= c.len_utf8();
                lc = (lc.0, lc.1 + 1);
            }
            None => break,
        }
    }
    lc
}

fn line_of(input: &str, pos: usize) -> &str {
    let start = if input.is_empty() {
        0
    } else {
        match input.char_indices().rev().skip_while(|&(i, _)| i >= pos).find(|&(_, c)| c == '\n') {
            Some((i, _)) => i + 1,
            None => 0,
        }
    };
    let end = if input.is_empty() {
        0
    } else if pos == input.len().wrapping_sub(1) {
        input.len()
    } else {
        match input.char_indices().skip_while(|&(i, _)| i < pos).find(|&(_, c)| c == '\n') {
            Some((i, _)) => i + 1,
            None => input.len(),
        }
    };
    &input[start..end]
}

pub fn format_error(g: &Grammar, input: &str, err: &ParseError) -> String {
    let message = {
        let pos: Vec<&str> = err.positives.iter().map(|&r| g.name(r)).collect();
        let neg: Vec<&str> = err.negatives.iter().map(|&r| g.name(r)).collect();
        match (neg.is_empty(), pos.is_empty()) {
            (false, false) => format!("unexpected {}; expected {}", enumerate(&neg), enumerate(&pos)),
            (false, true) => format!("unexpected {}", enumerate(&neg)),
            (true, false) => format!("expected {}", enumerate(&pos)),
            (true, true) => "unknown parsing error".to_string(),
        }
    };
    format_with_message(input, err.pos, &message)
}

pub fn format_with_message(input: &str, pos: usize, message: &str) -> String {
    let (ln, col) = line_col(input, pos);
    let at = input[pos..].chars().next();
    let raw = line_of(input, pos);
    let line = if at == Some('\n') || at == Some('\r') {
        raw.replace('\r', "\u{240d}").replace('\n', "\u{240a}")
    } else {
        raw.replace(&['\r', '\n'][..], "")
    };
    let spacing: String = " ".repeat(format!("{}", ln).len());
    let mut underline = String::new();
    for c in line.chars().take(col - 1) {
        if c == '\t' {
            underline.push('\t');
        } else {
            underline.push(' ');
        }
    }
    underline.push_str("^---");
    format!(
        "{s}--> {ls}:{c}\n{s} |\n{ls} | {line}\n{s} | {u}\n{s} |\n{s} = {m}",
        s = spacing,
        ls = ln,
        c = col,
        line = line,
        u = underline,
        m = message
    )
}
