// Shell grammar. The declaration order of rules matters: it is used to sort
// the rule names reported in parse error messages.
pub const SHELL_GRAMMAR: &str = r#"
WHITESPACE = _{ " " | "\t" | "\r" | "\\\n" }
COMMENT = _{ "#" ~ (!"\n" ~ ANY)* }

var_name = @{ (ASCII_ALPHANUMERIC | "_")+ }
num = @{ ASCII_DIGIT+ }

factor = !{ factor_sign? ~ (num | param_ex_span | "$"? ~ var_name | "(" ~ assign ~ ")") ~ incdec? }
factor_sign = _{ "+" | "-" }
incdec = _{ "++" | "--" }
term = !{ factor ~ (factor_op ~ term)? }
arith = !{ term ~ (arith_op ~ arith)? }
comp = !{ arith ~ (comp_op ~ assign)? }
assign = !{ var_name ~ assign_op ~ assign | comp }
comp_op = { "==" | "!=" | "<=" | ">=" | "<" | ">" }
assign_op = { "=" }
arith_op = { "+" | "-" }
factor_op = { "*" | "/" }

reserved_word = @{ ("if" | "then" | "else" | "elif" | "fi" | "for" | "in" | "done" | "do" | "case" | "esac" | "while" | "function" | "local" | "return" | "break" | "continue" | "[[") ~ !(escaped_char | unescaped_char) }

word = ${ assign_like? ~ (tilde_span ~ span* | span+) }
assign_like = _{ (ASCII_ALPHANUMERIC | "_" | "-")+ ~ "=" }
span = _{ literal_span | any_string_span | any_char_span | expr_span | command_span | proc_subst_span | backtick_span | param_ex_span | param_span | double_quoted_span | single_quoted_span }
escaped_char = @{ "\\" ~ ANY }
unescaped_char = @{ !(" " | "\t" | "\r" | "\n" | ";" | "&" | "|" | "<" | ">" | "(" | ")" | "{" | "}" | "$" | "`" | "\"" | "'" | "\\" | "*" | "?") ~ ANY }
literal_span = ${ (escaped_char | unescaped_char)+ }
tilde_span = @{ "~" ~ (!"/" ~ (escaped_char | unescaped_char))* }
any_string_span = { "*" }
any_char_span = { "?" }
command_span = !{ "$(" ~ compound_list ~ ")" }
proc_subst_direction = { "<(" | ">(" }
proc_subst_span = !{ proc_subst_direction ~ compound_list ~ ")" }
backtick_span = !{ "`" ~ compound_list ~ "`" }
expr_span = !{ "$((" ~ assign ~ "))" }
param_ex_span = ${ "${" ~ !"#" ~ param_name ~ index? ~ (param_op ~ word?)? ~ "}" }
param_span = ${ "$" ~ param_name | "${" ~ length_op ~ param_name ~ index? ~ (param_op ~ word?)? ~ "}" }
length_op = { "#" }
param_name = _{ var_name | special_param }
special_param = { "?" | "$" | "!" | "#" | "@" | "*" | "-" }
index = _{ "[" ~ assign ~ "]" }
literal_in_double_quoted_span = @{ (!("\"" | "\\" | "`" | "$") ~ ANY | "\\" ~ ANY)+ }
double_quoted_span = ${ "\"" ~ (expr_span | command_span | backtick_span | param_ex_span | param_span | literal_in_double_quoted_span)* ~ "\"" }
literal_in_single_quoted_span = @{ (!"'" ~ ANY)+ }
single_quoted_span = ${ "'" ~ literal_in_single_quoted_span* ~ "'" }

array_initializer = { "(" ~ word* ~ ")" }
initializer = { array_initializer | word }
assignment = { var_name ~ index? ~ "=" ~ initializer }

cond_op = { "==" | "!=" | "=" | "-eq" | "-ne" | "-lt" | "-le" | "-gt" | "-ge" | "&&" | "||" }
cond_term = { word | "(" ~ cond_expr ~ ")" }
cond_expr = { cond_term ~ (cond_op ~ cond_term)* }
cond_ex = { "[[" ~ cond_expr ~ "]]" }

redirect_direction = { ">>" | ">" | "<" }
redirect_to_fd = { "&" ~ ASCII_DIGIT* }
redirect_fd = { ASCII_DIGIT* }
redirect = { redirect_fd ~ redirect_direction ~ (word | redirect_to_fd) }
heredoc = { "<<" ~ PUSH(heredoc_marker) }
heredoc_marker = @{ (!(" " | "\t" | "\r" | "\n" | ";" | "&" | "|" | "<" | ">" | "(" | ")" | "{" | "}" | "$" | "`" | "\"" | "'" | "*" | "?") ~ ANY)+ }
heredoc_line = { word* ~ "\n" }
heredoc_body = { (!PEEK ~ heredoc_line)* ~ POP }

normal_newline = { "\n" }
newline = _{ normal_newline ~ (&DROP ~ heredoc_body)* ~ !DROP }

elif_part = { "elif" ~ compound_list ~ "then" ~ compound_list }
else_part = { "else" ~ compound_list }

command = { if_command | while_command | for_command | arith_for_command | case_command | group | subshell | cond_ex | local_definition | return_command | break_command | continue_command | function_definition | simple_command | assignment_command }

and_or_list_sep = { "&&" | "||" }
compound_list_sep = { (!";;" ~ ";" | "&" | newline) ~ newline* }

arith_for_exprs = { "((" ~ assign ~ ";" ~ assign ~ ";" ~ assign ~ "))" }
param_op = { ":-" | "-" | ":=" | "=" | "//" | "/" }

if_command = { "if" ~ compound_list ~ "then" ~ compound_list ~ elif_part* ~ else_part? ~ "fi" }
while_command = { "while" ~ compound_list ~ "do" ~ compound_list ~ "done" }
for_command = { "for" ~ var_name ~ "in" ~ (!reserved_word ~ word)* ~ (";" | newline) ~ newline* ~ "do" ~ compound_list ~ "done" }
arith_for_command = { "for" ~ arith_for_exprs ~ (";" | newline) ~ newline* ~ "do" ~ compound_list ~ "done" }
case_item = { word ~ ("|" ~ word)* ~ ")" ~ compound_list ~ ";;" ~ newline* }
case_command = { "case" ~ word ~ "in" ~ newline* ~ case_item* ~ "esac" }
group = { "{" ~ compound_list ~ "}" }
subshell = { "(" ~ compound_list ~ ")" }
local_definition = { "local" ~ (var_name ~ ("=" ~ initializer)?)+ }
return_command = { "return" ~ num? }
break_command = { "break" }
continue_command = { "continue" }
function_definition = { ("function" ~ var_name | var_name) ~ "()" ~ newline* ~ command }
simple_command = { assignment* ~ !reserved_word ~ word ~ (redirect | heredoc | word)* }
assignment_command = { assignment+ }

pipeline = { command ~ ("|" ~ newline* ~ command)* }
and_or_list = { pipeline ~ (and_or_list_sep ~ newline* ~ pipeline)* }
compound_list = { compound_list_sep* ~ (and_or_list ~ (compound_list_sep+ ~ and_or_list)*)? ~ compound_list_sep* }
script = { SOI ~ compound_list ~ EOI }
"#;

