    CString::new(s.as_bytes().iter().map(|&b| if b == 0 { b'?' } else { b }).collect::<Vec<u8>>()).unwrap()
}

pub fn wifexited(s: c_int) -> bool {
    (s & 0x7f) == 0
}
pub fn wexitstatus(s: c_int) -> i32 {
    (s >> 8) & 0xff
}
pub fn wifsignaled(s: c_int) -> bool {
    ((s & 0x7f) + 1) as i8 >= 2
}
pub fn wifstopped(s: c_int) -> bool {
    (s & 0xff) == 0x7f
}
pub fn wtermsig(s: c_int) -> i32 {
    s & 0x7f
}

pub fn write_all(fd: i32, data: &[u8]) -> Result<(), i32> {
    let mut off = 0;
    while off < data.len() {
        let n = unsafe { write(fd, data[off..].as_ptr() as *const c_void, data.len() - off) };
        if n < 0 {
            let e = errno();
            if e == 4 {
                continue;
            }
            return Err(e);
        }
        off += n as usize;
    }
    Ok(())
}

pub fn errno_name(e: i32) -> &'static str {
    match e {
        1 => "EPERM",
        2 => "ENOENT",
        3 => "ESRCH",
        4 => "EINTR",
        5 => "EIO",
        6 => "ENXIO",
        7 => "E2BIG",
