        30 => "EROFS",
        31 => "EMLINK",
        32 => "EPIPE",
        36 => "ENAMETOOLONG",
        40 => "ELOOP",
        _ => "UnknownErrno",
    }
}

pub fn errno_desc(e: i32) -> String {
    let s = std::io::Error::from_raw_os_error(e).to_string();
    // strip " (os error N)"
    match s.find(" (os error") {
        Some(i) => s[..i].to_string(),
        None => s,
    }
}
