// Converts the parse tree into the AST.
use crate::ast::*;
use crate::grammar;
use crate::peg::{self, Grammar, Pair};
use std::sync::OnceLock;

pub struct Rules {
    pub g: Grammar,
    pub alias_g: Grammar,
}

static RULES: OnceLock<Rules> = OnceLock::new();

pub fn rules() -> &'static Rules {
    RULES.get_or_init(|| Rules {
        g: Grammar::new(grammar::SHELL_GRAMMAR),
        alias_g: Grammar::new(grammar::ALIAS_GRAMMAR),
    })
}

pub enum ParseError {
    Fatal(String),
    Empty,
}

struct Builder<'a> {
    g: &'a Grammar,
    input: &'a str,
    heredoc_starts: Vec<usize>,
}

impl<'a> Builder<'a> {
    fn name(&self, p: &Pair) -> &'a str {
        self.g.name(p.rule)
    }
    fn text(&self, p: &Pair) -> &'a str {
        &self.input[p.start..p.end]
    }
    fn is(&self, p: &Pair, n: &str) -> bool {
        self.name(p) == n
    }
    fn is_nl(&self, p: &Pair) -> bool {
        let n = self.name(p);
        n == "normal_newline" || n == "newline"
    }

    fn compound_list(&self, p: &Pair) -> Vec<Term> {
        // children: compound_list_sep / and_or_list
        let mut terms: Vec<Term> = Vec::new();
        for c in &p.children {
            match self.name(c) {
                "and_or_list" => terms.push(self.and_or_list(c)),
                "compound_list_sep" => {
                    let t = self.text(c);
                    if t.starts_with('&') {
                        if let Some(last) = terms.last_mut() {
                            last.background = true;
                        }
                    }
                }
                // a non-compound_list pair (quirk): yields nothing
                _ => {}
            }
        }
        terms
    }

    fn and_or_list(&self, p: &Pair) -> Term {
        let code = self.text(p).to_string();
        let mut it = p.children.iter();
        let mut pipelines = Vec::new();
        if let Some(first) = it.next() {
            pipelines.push((RunIf::Always, self.pipeline(first)));
        }
        loop {
            let sep = match it.next() {
                Some(s) => s,
                None => break,
            };
            if !self.is(sep, "and_or_list_sep") {
                break;
            }
            let run_if = if self.text(sep) == "&&" { RunIf::Success } else { RunIf::Failure };
            let mut next = match it.next() {
                Some(n) => n,
                None => break,
            };
            if self.is_nl(next) {
                next = match it.next() {
                    Some(n) => n,
                    None => break,
                };
            }
            if self.is(next, "pipeline") {
                pipelines.push((run_if, self.pipeline(next)));
            } else {
                pipelines.push((run_if, Pipeline { commands: vec![] }));
                break;
            }
        }
        Term { code, pipelines, background: false }
    }

    fn pipeline(&self, p: &Pair) -> Pipeline {
        let mut it = p.children.iter();
        let mut commands = Vec::new();
        if let Some(first) = it.next() {
            commands.push(self.command(first));
        }
        while let Some(mut c) = it.next() {
            if self.is_nl(c) {
                c = match it.next() {
                    Some(n) => n,
                    None => break,
                };
            }
            commands.push(self.command(c));
        }
        Pipeline { commands }
    }

    fn command(&self, p: &Pair) -> Command {
        if !self.is(p, "command") {
            crate::nsh_panic("src/parser.rs:1201:18", "internal error: entered unreachable code");
        }
        let inner = &p.children[0];
        match self.name(inner) {
            "simple_command" => self.simple_command(inner),
            "assignment_command" => Command::Assignment {
                assignments: inner.children.iter().map(|a| self.assignment(a)).collect(),
            },
            "if_command" => self.if_command(inner),
            "while_command" => {
                let cond = self.compound_list(&inner.children[0]);
                let body = self.compound_list(&inner.children[1]);
                Command::While { condition: cond, body }
            }
            "for_command" => self.for_command(inner),
            "arith_for_command" => self.arith_for_command(inner),
            "case_command" => self.case_command(inner),
            "group" => Command::Group { terms: self.compound_list(&inner.children[0]) },
            "subshell" => Command::SubShell { terms: self.compound_list(&inner.children[0]) },
            "cond_ex" => Command::Cond(Box::new(self.cond_expr(&inner.children[0]))),
            "local_definition" => self.local_definition(inner),
            "return_command" => {
                let status = inner.children.get(0).map(|n| self.parse_num(n));
                Command::Return { status }
            }
            "break_command" => Command::Break,
            "continue_command" => Command::Continue,
            "function_definition" => {
                let name = self.text(&inner.children[0]).to_string();
                let mut it = inner.children[1..].iter();
                let mut body = it.next().unwrap();
                if self.is_nl(body) {
                    body = it.next().unwrap();
                }
                let body = self.command(body);
                Command::FunctionDef { name, body: Box::new(body) }
            }
            _ => crate::nsh_panic("src/parser.rs:1201:18", "internal error: entered unreachable code"),
        }
    }

    fn parse_num(&self, p: &Pair) -> i32 {
        match self.text(p).parse::<i32>() {
            Ok(n) => n,
            Err(e) => crate::nsh_panic(
                "src/parser.rs:492:67",
                &format!("called `Result::unwrap()` on an `Err` value: {:?}", e),
            ),
        }
    }

    fn if_command(&self, p: &Pair) -> Command {
        let condition = self.compound_list(&p.children[0]);
        let then_part = self.compound_list(&p.children[1]);
        let mut elif_parts = Vec::new();
        let mut else_part = None;
        for c in &p.children[2..] {
            match self.name(c) {
                "elif_part" => elif_parts.push(ElIf {
                    condition: self.compound_list(&c.children[0]),
                    then_part: self.compound_list(&c.children[1]),
                }),
                "else_part" => else_part = Some(self.compound_list(&c.children[0])),
                _ => {}
            }
        }
        Command::If { condition, then_part, elif_parts, else_part }
    }

    fn for_command(&self, p: &Pair) -> Command {
        let var_name = self.text(&p.children[0]).to_string();
        let mut words = Vec::new();
        let mut it = p.children[1..].iter().peekable();
        while let Some(c) = it.peek() {
            if self.is(c, "word") {
                words.push(self.word(c));
                it.next();
            } else {
                break;
            }
        }
        let mut body = it.next();
        if let Some(b) = body {
            if self.is_nl(b) {
                body = it.next();
            }
        }
        let body = match body {
            Some(b) if self.is(b, "compound_list") => self.compound_list(b),
            _ => vec![],
        };
        Command::For { var_name, words, body }
    }

    fn arith_for_command(&self, p: &Pair) -> Command {
        let exprs = &p.children[0];
        let init = self.expr(&exprs.children[0]);
        let cond = self.expr(&exprs.children[1]);
        let update = self.expr(&exprs.children[2]);
        let mut it = p.children[1..].iter();
        let mut body = it.next();
        if let Some(b) = body {
            if self.is_nl(b) {
                body = it.next();
            }
        }
        let body = match body {
            Some(b) if self.is(b, "compound_list") => self.compound_list(b),
            _ => vec![],
        };
        Command::ArithFor { init, cond, update, body }
    }

    fn case_command(&self, p: &Pair) -> Command {
        let word = self.word(&p.children[0]);
        let mut items = Vec::new();
        for c in &p.children[1..] {
            if self.is(c, "case_item") {
                let mut patterns = Vec::new();
                let mut body = vec![];
                for cc in &c.children {
                    match self.name(cc) {
                        "word" => patterns.push(self.word(cc)),
                        "compound_list" => body = self.compound_list(cc),
                        _ => {}
                    }
                }
                items.push(CaseItem { patterns, body });
            }
        }
        Command::Case { word, items }
    }

    fn local_definition(&self, p: &Pair) -> Command {
        let mut declarations = Vec::new();
        for c in &p.children {
            match self.name(c) {
                "var_name" => declarations.push(LocalDeclaration { name: self.text(c).to_string(), initializer: None }),
                "initializer" => {
                    if let Some(last) = declarations.last_mut() {
                        last.initializer = Some(self.initializer(c));
                    }
                }
                _ => {}
            }
        }
        Command::LocalDef { declarations }
    }

    fn initializer(&self, p: &Pair) -> Initializer {
        let c = &p.children[0];
        if self.is(c, "array_initializer") {
            Initializer::Array(c.children.iter().map(|w| self.word(w)).collect())
        } else {
            Initializer::String(self.word(c))
        }
    }

    fn assignment(&self, p: &Pair) -> Assignment {
        let name = self.text(&p.children[0]).to_string();
        let mut index = None;
        let mut initializer = Initializer::String(Word(vec![]));
        for c in &p.children[1..] {
            match self.name(c) {
                "assign" => index = Some(self.expr(c)),
                "initializer" => initializer = self.initializer(c),
                _ => {}
            }
        }
        Assignment { name, initializer, index }
    }

    fn simple_command(&self, p: &Pair) -> Command {
        let mut argv = Vec::new();
        let mut redirects = Vec::new();
        let mut assignments = Vec::new();
        for c in &p.children {
            match self.name(c) {
                "assignment" => assignments.push(self.assignment(c)),
                "word" => argv.push(self.word(c)),
                "redirect" => redirects.push(self.redirect(c)),
                "heredoc" => {
                    let idx = self.heredoc_starts.iter().filter(|&&s| s < c.start).count();
                    redirects.push(Redirection {
                        fd: 0,
                        direction: RedirectionDirection::Input,
                        target: RedirectionTarget::HereDoc(idx),
                    });
                }
                _ => {}
            }
        }
        Command::SimpleCommand { argv, redirects, assignments }
    }

    fn redirect(&self, p: &Pair) -> Redirection {
        let fd_text = self.text(&p.children[0]);
        let dir_text = self.text(&p.children[1]);
        let (direction, default_fd) = match dir_text {
            ">>" => (RedirectionDirection::Append, 1),
            ">" => (RedirectionDirection::Output, 1),
            _ => (RedirectionDirection::Input, 0),
        };
        let fd = fd_text.parse::<i32>().unwrap_or(default_fd);
        let t = &p.children[2];
        let target = if self.is(t, "redirect_to_fd") {
            let s = &self.text(t)[1..];
            RedirectionTarget::Fd(s.parse::<i32>().unwrap_or(-1))
        } else {
            RedirectionTarget::File(self.word(t))
        };
        Redirection { fd, direction, target }
    }

    // ---- words ----

    pub fn word(&self, p: &Pair) -> Word {
        let mut spans = Vec::new();
        // assign-like prefix (silent rule) is the text before the first child.
        let first_start = p.children.get(0).map(|c| c.start).unwrap_or(p.end);
        if first_start > p.start {
            spans.push(Span::Literal(self.input[p.start..first_start].to_string(), false));
        }
        for c in &p.children {
            self.span(c, &mut spans, false);
        }
        Word(spans)
    }

    fn span(&self, c: &Pair, spans: &mut Vec<Span>, quoted: bool) {
        match self.name(c) {
            "literal_span" => {
                let mut cur = String::new();
                for ch in &c.children {
                    let t = self.text(ch);
                    if self.is(ch, "escaped_char") {
                        if !cur.is_empty() {
                            spans.push(Span::Literal(std::mem::take(&mut cur), false));
                        }
                        spans.push(Span::Literal(t[1..].to_string(), true));
                    } else {
                        cur.push_str(t);
                    }
                }
                if !cur.is_empty() {
                    spans.push(Span::Literal(cur, false));
                }
            }
            "tilde_span" => {
                let t = self.text(c);
                if t.len() == 1 {
                    spans.push(Span::Tilde(None));
                } else {
                    spans.push(Span::Tilde(Some(t[1..].to_string())));
                }
            }
            "any_string_span" => spans.push(Span::AnyString),
            "any_char_span" => spans.push(Span::AnyChar),
            "command_span" | "backtick_span" => {
                let body = self.compound_list(&c.children[0]);
                spans.push(Span::Command { body, quoted });
            }
            "proc_subst_span" => {
                let dir = self.text(&c.children[0]);
                let body = self.compound_list(&c.children[1]);
                spans.push(Span::ProcSubst { body, input: dir == "<(" });
            }
            "expr_span" => {
                let e = self.expr(&c.children[0]);
                spans.push(Span::Arith(Box::new(e)));
            }
            "param_ex_span" | "param_span" => spans.push(self.param(c, quoted)),
            "double_quoted_span" => {
                let n = spans.len();
                for cc in &c.children {
                    if self.is(cc, "literal_in_double_quoted_span") {
                        let t = self.text(cc);
                        let mut s = String::new();
                        let mut chars = t.chars().peekable();
                        while let Some(ch) = chars.next() {
                            if ch == '\\' {
                                match chars.peek() {
                                    Some('"') | Some('$') | Some('`') => {
                                        s.push(chars.next().unwrap());
                                    }
                                    _ => s.push('\\'),
                                }
                            } else {
                                s.push(ch);
                            }
                        }
                        spans.push(Span::Literal(s, true));
                    } else {
                        self.span(cc, spans, true);
                    }
                }
                if spans.len() == n {
                    spans.push(Span::Literal(String::new(), true));
                }
            }
            "single_quoted_span" => {
                let t = self.text(c);
                spans.push(Span::Literal(t[1..t.len() - 1].to_string(), true));
            }
            _ => {}
        }
    }

    fn param(&self, c: &Pair, quoted: bool) -> Span {
        let t = self.text(c);
        let length = t.starts_with("${#");
        let braced = t.starts_with("${");
        // name: var_name child, or special char
        let name_start = if length { 3 } else if braced { 2 } else { 1 };
        let mut name = String::new();
        let mut index = None;
        let mut op_text: Option<&str> = None;
        let mut op_word: Option<Word> = None;
        for cc in &c.children {
            match self.name(cc) {
                "var_name" => name = self.text(cc).to_string(),
                "assign" => index = Some(Box::new(self.expr(cc))),
                "param_op" => op_text = Some(self.text(cc)),
                "word" => op_word = Some(self.word(cc)),
                _ => {}
            }
        }
        if name.is_empty() {
            name = t[name_start..].chars().next().map(|c| c.to_string()).unwrap_or_default();
        }
        let op = if length {
            ExpandOp::Length
        } else {
            match op_text {
                None => ExpandOp::GetOrEmpty,
                Some(o) => {
                    let w = op_word.unwrap_or(Word(vec![]));
                    match o {
                        ":-" => ExpandOp::GetOrDefault(w),
                        "-" => ExpandOp::GetNullableOrDefault(w),
                        ":=" => ExpandOp::GetOrDefaultAndAssign(w),
                        "=" => ExpandOp::GetNullableOrDefaultAndAssign(w),
                        "/" | "//" => {
                            let (pattern, replacement) = split_subst(w);
                            ExpandOp::Subst { pattern, replacement, global: o == "//" }
                        }
                        _ => ExpandOp::GetOrEmpty,
                    }
                }
            }
        };
        Span::Param { name, op, index, quoted }
    }

    // ---- arithmetic ----

    fn expr(&self, p: &Pair) -> Expr {
        match self.name(p) {
            "assign" => {
                let c = &p.children;
                if c.len() == 3 && self.is(&c[0], "var_name") && self.is(&c[1], "assign_op") {
                    Expr::Assign(self.text(&c[0]).to_string(), Box::new(self.expr(&c[2])))
                } else {
                    self.expr(&c[0])
                }
            }
            "comp" => {
                let c = &p.children;
                let lhs = self.expr(&c[0]);
                if c.len() == 3 {
                    let rhs = Box::new(self.expr(&c[2]));
                    let lhs = Box::new(lhs);
                    match self.text(&c[1]) {
                        "==" => Expr::Eq(lhs, rhs),
                        "!=" => Expr::Ne(lhs, rhs),
                        "<=" => Expr::Le(lhs, rhs),
                        ">=" => Expr::Ge(lhs, rhs),
                        "<" => Expr::Lt(lhs, rhs),
                        _ => Expr::Gt(lhs, rhs),
                    }
                } else {
                    lhs
                }
            }
            "arith" => {
                let c = &p.children;
                let lhs = self.expr(&c[0]);
                if c.len() == 3 {
                    let rhs = Box::new(self.expr(&c[2]));
                    if self.text(&c[1]) == "+" {
                        Expr::Add(Box::new(lhs), rhs)
                    } else {
                        Expr::Sub(Box::new(lhs), rhs)
                    }
                } else {
                    lhs
                }
            }
            "term" => {
                let c = &p.children;
                let lhs = self.expr(&c[0]);
                if c.len() == 3 {
                    let rhs = Box::new(self.expr(&c[2]));
                    if self.text(&c[1]) == "*" {
                        Expr::Mul(Box::new(lhs), rhs)
                    } else {
                        Expr::Div(Box::new(lhs), rhs)
                    }
                } else {
                    lhs
                }
            }
            "factor" => {
                let t = self.text(p).trim_end();
                let neg = t.starts_with('-');
                let inc = t.ends_with("++");
                let dec = t.ends_with("--");
                let c = &p.children[0];
                match self.name(c) {
                    "num" => {
                        let n = self.parse_num(c);
                        Expr::Num(if neg { n.wrapping_neg() } else { n })
                    }
                    "var_name" => {
                        let name = self.text(c).to_string();
                        if inc {
                            Expr::Inc(name)
                        } else if dec {
                            Expr::Dec(name)
                        } else {
                            Expr::Var(name)
                        }
                    }
                    "assign" => Expr::Paren(Box::new(self.expr(c))),
                    _ => crate::nsh_panic("src/parser.rs:508:18", "internal error: entered unreachable code"),
                }
            }
            _ => crate::nsh_panic("src/parser.rs:508:18", "internal error: entered unreachable code"),
        }
    }

    // ---- [[ ]] ----

    fn cond_expr(&self, p: &Pair) -> CondExpr {
        // children: cond_term (cond_op cond_term)*
        let mut terms: Vec<CondExpr> = Vec::new();
        let mut ops: Vec<&str> = Vec::new();
        for c in &p.children {
            match self.name(c) {
                "cond_term" => terms.push(self.cond_term(c)),
                "cond_op" => ops.push(self.text(c)),
                _ => {}
            }
        }
        build_cond(terms, ops)
    }

    fn cond_term(&self, p: &Pair) -> CondExpr {
        let c = &p.children[0];
        if self.is(c, "word") {
            CondExpr::Word(self.word(c))
        } else {
            crate::nsh_panic("src/parser.rs:661:18", "internal error: entered unreachable code")
        }
    }
}

fn prec(op: &str) -> u8 {
    match op {
        "||" => 1,
        "&&" => 2,
        _ => 3,
    }
}

fn build_cond(terms: Vec<CondExpr>, ops: Vec<&str>) -> CondExpr {
    // precedence climbing, left associative
    let mut terms = terms.into_iter();
    let mut ops = ops.into_iter().peekable();
    fn climb<'a>(
        lhs: CondExpr,
        min: u8,
        terms: &mut std::vec::IntoIter<CondExpr>,
        ops: &mut std::iter::Peekable<std::vec::IntoIter<&'a str>>,
    ) -> CondExpr {
        let mut lhs = lhs;
        while let Some(&op) = ops.peek() {
            let p = prec(op);
            if p < min {
                break;
            }
            ops.next();
            let mut rhs = terms.next().unwrap();
            while let Some(&op2) = ops.peek() {
                if prec(op2) > p {
                    rhs = climb(rhs, prec(op2), terms, ops);
                } else {
                    break;
                }
            }
            let (l, r) = (Box::new(lhs), Box::new(rhs));
            lhs = match op {
                "||" => CondExpr::Or(l, r),
                "&&" => CondExpr::And(l, r),
                "==" | "=" => CondExpr::StrEq(l, r),
                "!=" => CondExpr::StrNe(l, r),
                "-eq" => CondExpr::Eq(l, r),
                "-ne" => CondExpr::Ne(l, r),
                "-lt" => CondExpr::Lt(l, r),
                "-le" => CondExpr::Le(l, r),
                "-gt" => CondExpr::Gt(l, r),
                _ => CondExpr::Ge(l, r),
            };
        }
        lhs
    }
    let first = terms.next().unwrap();
    climb(first, 0, &mut terms, &mut ops)
}

// Split the word of ${x/pattern/replacement}.
fn split_subst(w: Word) -> (Word, String) {
    let mut pattern = Vec::new();
    let mut replacement: Option<String> = None;
    for span in w.0 {
        match span {
            Span::Literal(s, false) if replacement.is_none() && s.contains('/') => {
                let i = s.find('/').unwrap();
                if i > 0 {
                    pattern.push(Span::Literal(s[..i].to_string(), false));
                }
                replacement = Some(s[i + 1..].to_string());
            }
            Span::Literal(s, q) if replacement.is_some() && !q => {
                // subsequent literal spans: part of the replacement text
                pattern.push(Span::Literal(s, q));
            }
            other => pattern.push(other),
        }
    }
    (Word(pattern), replacement.unwrap_or_default())
}

fn collect_heredoc_starts(b: &Builder, p: &Pair, out: &mut Vec<usize>) {
    if b.is(p, "heredoc") {
        out.push(p.start);
    }
    for c in &p.children {
        collect_heredoc_starts(b, c, out);
    }
}

fn collect_heredoc_bodies(b: &Builder, p: &Pair, out: &mut Vec<Vec<Vec<Word>>>) {
    if b.is(p, "heredoc_body") {
        let mut lines = Vec::new();
        for l in &p.children {
            if b.is(l, "heredoc_line") {
                lines.push(l.children.iter().filter(|w| b.is(w, "word")).map(|w| b.word(w)).collect());
            }
        }
        out.push(lines);
        return;
    }
    for c in &p.children {
        collect_heredoc_bodies(b, c, out);
    }
}

pub fn parse(input: &str) -> Result<Ast, ParseError> {
    let r = rules();
    let g = &r.g;
    match g.parse(g.id("script"), input) {
        Ok(pairs) => {
            let script = &pairs[0];
            let mut b = Builder { g, input, heredoc_starts: vec![] };
            let mut starts = Vec::new();
            collect_heredoc_starts(&b, script, &mut starts);
            b.heredoc_starts = starts;
            let mut heredocs = Vec::new();
            collect_heredoc_bodies(&b, script, &mut heredocs);
            let cl = script.children.iter().find(|c| b.is(c, "compound_list")).unwrap();
            let terms = b.compound_list(cl);
            // resolve here documents of top-level commands
            for t in &terms {
                for (_, p) in &t.pipelines {
                    for c in &p.commands {
                        if let Command::SimpleCommand { redirects, .. } = c {
                            for r in redirects {
                                if let RedirectionTarget::HereDoc(i) = r.target {
                                    if i >= heredocs.len() {
                                        crate::nsh_panic(
                                            "src/parser.rs:1326:62",
                                            &format!("index out of bounds: the len is {} but the index is {}", heredocs.len(), i),
                                        );
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if terms.is_empty() {
                return Err(ParseError::Empty);
            }
            Ok(Ast { terms, heredocs })
        }
        Err(e) => Err(ParseError::Fatal(peg::format_error(g, input, &e))),
    }
}

pub fn parse_alias(input: &str) -> Result<(String, String), String> {
    let r = rules();
    let g = &r.alias_g;
    match g.parse(g.id("alias"), input) {
        Ok(pairs) => {
            let a = &pairs[0];
            let mut name = String::new();
            let mut value = String::new();
            for c in &a.children {
                match g.name(c.rule) {
                    "alias_name" => name = input[c.start..c.end].to_string(),
                    "alias_value" => value = input[c.start..c.end].to_string(),
                    _ => {}
                }
            }
            Ok((name, value))
        }
        Err(e) => Err(peg::format_error(g, input, &e)),
    }
}
