        self.find(text.as_bytes(), 0).is_some()
    }

    pub fn replace(&self, text: &str, rep: &str, global: bool) -> String {
        let t = text.as_bytes();
        let mut out: Vec<u8> = Vec::new();
        let mut pos = 0;
        loop {
            match self.find(t, pos) {
                Some((s, e)) => {
                    out.extend_from_slice(&t[pos..s]);
                    out.extend_from_slice(rep.as_bytes());
                    pos = e + 1;
                    if !global {
                        break;
                    }
                }
                None => break,
            }
        }
        if pos < t.len() {
            out.extend_from_slice(&t[pos..]);
        }
        String::from_utf8_lossy(&out).into_owned()
    }
