// Pathname expansion compatible with the classic `glob` crate semantics.
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, PartialEq)]
enum CharSpec {
    Single(char),
    Range(char, char),
}

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Char(char),
    AnyChar,
    AnySeq,
    AnyRecSeq,
    AnyWithin(Vec<CharSpec>),
    AnyExcept(Vec<CharSpec>),
}

#[derive(Debug, Clone)]
pub struct PatternError {
    pub pos: usize,
    pub msg: &'static str,
}

#[derive(Debug, Clone)]
struct GPattern {
    tokens: Vec<Tok>,
    is_recursive: bool,
}

#[derive(PartialEq)]
enum MR {
    Match,
    SubNo,
    EntireNo,
}

fn parse_specs(s: &[char]) -> Vec<CharSpec> {
    let mut cs = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if i + 3 <= s.len() && s[i + 1] == '-' {
            cs.push(CharSpec::Range(s[i], s[i + 2]));
            i += 3;
        } else {
            cs.push(CharSpec::Single(s[i]));
            i += 1;
        }
    }
    cs
}

impl GPattern {
    fn new(pattern: &str) -> Result<GPattern, PatternError> {
        let chars: Vec<char> = pattern.chars().collect();
        let mut tokens = Vec::new();
        let mut is_recursive = false;
        let mut i = 0;
        while i < chars.len() {
            match chars[i] {
                '?' => {
                    tokens.push(Tok::AnyChar);
                    i += 1;
                }
                '*' => {
                    let old = i;
                    while i < chars.len() && chars[i] == '*' {
                        i += 1;
                    }
                    let count = i - old;
                    if count > 2 {
                        return Err(PatternError { pos: old + 2, msg: "wildcards are either regular `*` or recursive `**`" });
                    } else if count == 2 {
                        let is_valid = if i == 2 || chars[i - count - 1] == '/' {
                            if i < chars.len() && chars[i] == '/' {
                                i += 1;
                                true
                            } else if i == chars.len() {
                                true
                            } else {
                                return Err(PatternError { pos: i, msg: "recursive wildcards must form a single path component" });
                            }
                        } else {
                            return Err(PatternError { pos: old - 1, msg: "recursive wildcards must form a single path component" });
                        };
                        if is_valid {
                            let l = tokens.len();
                            if !(l > 1 && tokens[l - 1] == Tok::AnyRecSeq) {
                                is_recursive = true;
                                tokens.push(Tok::AnyRecSeq);
                            }
                        }
                    } else {
                        tokens.push(Tok::AnySeq);
                    }
                }
                '[' => {
                    if i + 4 <= chars.len() && chars[i + 1] == '!' {
                        if let Some(j) = chars[i + 3..].iter().position(|x| *x == ']') {
                            let cs = parse_specs(&chars[i + 2..i + 3 + j]);
                            tokens.push(Tok::AnyExcept(cs));
                            i += j + 4;
                            continue;
                        }
                    } else if i + 3 <= chars.len() && chars[i + 1] != '!' {
                        if let Some(j) = chars[i + 2..].iter().position(|x| *x == ']') {
                            let cs = parse_specs(&chars[i + 1..i + 2 + j]);
                            tokens.push(Tok::AnyWithin(cs));
                            i += j + 3;
                            continue;
                        }
                    }
                    return Err(PatternError { pos: i, msg: "invalid range pattern" });
                }
                c => {
                    tokens.push(Tok::Char(c));
                    i += 1;
                }
            }
        }
        Ok(GPattern { tokens, is_recursive })
    }

    fn matches(&self, s: &str) -> bool {
        let chars: Vec<char> = s.chars().collect();
        self.matches_from(true, &chars, 0, 0) == MR::Match
    }

    fn matches_from(&self, mut follows_sep: bool, file: &[char], mut fi: usize, i: usize) -> MR {
        for (ti, token) in self.tokens[i..].iter().enumerate() {
            match token {
                Tok::AnySeq | Tok::AnyRecSeq => {
                    match self.matches_from(follows_sep, file, fi, i + ti + 1) {
                        MR::SubNo => {}
                        m => return m,
                    }
                    while fi < file.len() {
                        let c = file[fi];
                        fi += 1;
                        follows_sep = c == '/';
                        if *token == Tok::AnyRecSeq && !follows_sep {
                            continue;
                        }
                        match self.matches_from(follows_sep, file, fi, i + ti + 1) {
                            MR::SubNo => {}
                            m => return m,
                        }
                    }
                }
                _ => {
                    if fi >= file.len() {
                        return MR::EntireNo;
                    }
                    let c = file[fi];
                    fi += 1;
                    let is_sep = c == '/';
                    let ok = match token {
                        Tok::AnyChar => true,
                        Tok::AnyWithin(specs) => in_specs(specs, c),
                        Tok::AnyExcept(specs) => !in_specs(specs, c),
                        Tok::Char(c2) => c == *c2,
                        _ => unreachable!(),
                    };
                    if !ok {
                        return MR::SubNo;
                    }
                    follows_sep = is_sep;
                }
            }
        }
        if fi >= file.len() {
            MR::Match
        } else {
            MR::SubNo
        }
    }
}

fn in_specs(specs: &[CharSpec], c: char) -> bool {
    for s in specs {
        match *s {
            CharSpec::Single(sc) => {
                if c == sc {
                    return true;
                }
            }
            CharSpec::Range(a, b) => {
                if a <= c && c <= b {
                    return true;
                }
            }
        }
    }
    false
}

struct PW {
    path: PathBuf,
    is_dir: bool,
}

impl PW {
    fn from_path(p: PathBuf) -> PW {
        let is_dir = fs::metadata(&p).map(|m| m.is_dir()).unwrap_or(false);
        PW { path: p, is_dir }
    }
}

fn pattern_as_str(p: &GPattern) -> Option<String> {
    let mut s = String::new();
    for t in &p.tokens {
        match t {
            Tok::Char(c) => s.push(*c),
            _ => return None,
        }
    }
    Some(s)
}

fn fill_todo(todo: &mut Vec<(PW, usize)>, patterns: &[GPattern], idx: usize, path: &PW) {
    let add = |todo: &mut Vec<(PW, usize)>, next: PW| {
        if idx + 1 == patterns.len() {
            todo.push((next, usize::MAX));
        } else {
            fill_todo(todo, patterns, idx + 1, &next);
        }
    };
    let pattern = &patterns[idx];
    let is_dir = path.is_dir;
    let curdir = path.path.as_path() == Path::new(".");
    match pattern_as_str(pattern) {
        Some(s) => {
            let special = s == "." || s == "..";
            let next_path = if curdir { PathBuf::from(&s) } else { path.path.join(&s) };
            let next = PW::from_path(next_path);
            if (special && is_dir)
                || (!special && (fs::metadata(&next.path).is_ok() || fs::symlink_metadata(&next.path).is_ok()))
            {
                add(todo, next);
            }
        }
        None if is_dir => {
            if let Ok(rd) = fs::read_dir(&path.path) {
                let mut children: Vec<PW> = Vec::new();
                for e in rd.flatten() {
                    let p = if curdir { PathBuf::from(e.file_name()) } else { e.path() };
                    let is_dir = match e.file_type() {
                        Ok(ft) if !ft.is_symlink() => ft.is_dir(),
                        _ => fs::metadata(&p).map(|m| m.is_dir()).unwrap_or(false),
                    };
                    children.push(PW { path: p, is_dir });
                }
                children.sort_by(|a, b| b.path.file_name().cmp(&a.path.file_name()));
                for c in children {
                    todo.push((c, idx));
                }
                if !pattern.tokens.is_empty() && pattern.tokens[0] == Tok::Char('.') {
                    for special in [".", ".."] {
                        if pattern.matches(special) {
                            add(todo, PW::from_path(path.path.join(special)));
                        }
                    }
                }
            }
        }
        None => {}
    }
}

pub fn glob(pattern: &str) -> Result<Vec<String>, PatternError> {
    GPattern::new(pattern)?;
    let (root, rest_start) = if pattern.starts_with('/') {
        let n = pattern.len() - pattern.trim_start_matches('/').len();
        (Some(pattern[..n].to_string()), n)
    } else {
        (None, 0)
    };
    let mut dir_patterns = Vec::new();
    let rest = &pattern[rest_start..];
    let mut comps: Vec<&str> = rest.split('/').collect();
    if rest.ends_with('/') {
        comps.pop();
    }
    if rest.is_empty() {
        comps.clear();
    }
    for c in comps {
        dir_patterns.push(GPattern::new(c)?);
    }
    let require_dir = pattern.ends_with('/');
    let scope = match root {
        Some(r) => PW::from_path(PathBuf::from(r)),
        None => PW::from_path(PathBuf::from(".")),
    };
    let mut results = Vec::new();
    if dir_patterns.is_empty() {
        return Ok(results);
    }
    let mut todo: Vec<(PW, usize)> = Vec::new();
    fill_todo(&mut todo, &dir_patterns, 0, &scope);
    while let Some((path, mut idx)) = todo.pop() {
        if idx == usize::MAX {
            if require_dir && !path.is_dir {
                continue;
            }
            results.push(path.path.to_string_lossy().into_owned());
            continue;
        }
        if dir_patterns[idx].is_recursive {
            let mut next = idx;
            while next + 1 < dir_patterns.len() && dir_patterns[next + 1].is_recursive {
                next += 1;
            }
            if path.is_dir {
                fill_todo(&mut todo, &dir_patterns, next, &path);
                if next == dir_patterns.len() - 1 {
                    results.push(path.path.to_string_lossy().into_owned());
                    continue;
                } else {
                    idx = next + 1;
                }
            } else if next == dir_patterns.len() - 1 {
                continue;
            } else {
                idx = next + 1;
            }
        }
        let fname = match path.path.file_name().and_then(|s| s.to_str()) {
            Some(x) => x.to_string(),
            None => continue,
        };
        if dir_patterns[idx].matches(&fname) {
            if idx == dir_patterns.len() - 1 {
                if !require_dir || path.is_dir {
                    results.push(path.path.to_string_lossy().into_owned());
                }
            } else {
                fill_todo(&mut todo, &dir_patterns, idx + 1, &path);
            }
        }
    }
    Ok(results)
}
