// Word expansion.
use crate::ast::*;
use crate::eval::{Shell, Value};
use crate::pattern::{Frag, Pattern};

pub enum ExpandError {
    NoMatches,
    Undefined(String),
    GlobPanic(String),
}

#[derive(Clone, Debug)]
pub enum WFrag {
    Lit(String, bool),
    AnyChar,
    AnyString,
