impl Shell {
    pub fn ifs(&self) -> String {
        match self.get_var_str("IFS") {
            Some(s) => s,
            None => " \t\n".to_string(),
        }
    }

    /// Expands a word into a list of words (fragments), applying field
    /// splitting on unquoted expansions.
    pub fn expand_word_frags(&mut self, word: &Word) -> Result<Vec<Vec<WFrag>>, ExpandError> {
        let ifs = self.ifs();
        let mut words: Vec<Vec<WFrag>> = Vec::new();
        let mut current: Vec<WFrag> = Vec::new();
        for span in &word.0 {
            match span {
                Span::Literal(s, q) => current.push(WFrag::Lit(s.clone(), *q)),
                Span::Tilde(user) => {
                    if user.is_some() {
                        self.eprint("nsh: warning: ~user is not yet supported\n");
                    }
                    current.push(WFrag::Lit(self.home.clone(), true));
                }
                Span::AnyString => current.push(WFrag::AnyString),
                Span::AnyChar => current.push(WFrag::AnyChar),
                Span::Arith(e) => {
                    let v = self.eval_arith(e);
                    current.push(WFrag::Lit(v.to_string(), true));
                }
                Span::ProcSubst { body, input } => {
                    if !*input {
                        crate::nsh_panic("src/expand.rs:238:25", "not implemented");
                    }
                    let path = self.run_proc_subst(body);
                    current.push(WFrag::Lit(path, true));
                }
                Span::Param { .. } | Span::Command { .. } => {
                    let (frags, quoted) = match span {
                        Span::Param { name, op, index, quoted } => (self.expand_param(name, op, index.as_deref())?, *quoted),
                        Span::Command { body, quoted } => (vec![self.command_substitution(body)], *quoted),
                        _ => unreachable!(),
                    };
                    if quoted {
                        if frags.len() == 1 {
                            current.push(WFrag::Lit(frags[0].clone(), true));
                        } else {
                            for f in frags {
                                current.push(WFrag::Lit(f, true));
                                words.push(std::mem::take(&mut current));
                            }
                        }
                    } else {
                        for f in frags {
                            if !frags_empty(&current) {
                                words.push(std::mem::take(&mut current));
                            } else {
                                current.clear();
                            }
                            for piece in f.split(|c: char| ifs.contains(c)) {
                                words.push(vec![WFrag::Lit(piece.to_string(), true)]);
                            }
                        }
                    }
                }
            }
        }
        if !frags_empty(&current) || words.is_empty() {
            words.push(current);
        }
        Ok(words)
    }

    pub fn expand_word_into_vec(&mut self, word: &Word) -> Result<Vec<String>, ExpandError> {
        let words = self.expand_word_frags(word)?;
        let mut out = Vec::new();
        for w in words {
            let has_glob = w.iter().any(|f| matches!(f, WFrag::AnyChar | WFrag::AnyString));
            if has_glob {
                let mut pat = String::new();
                for f in &w {
                    match f {
                        WFrag::Lit(s, _) => {
                            for c in s.chars() {
                                match c {
                                    '*' => pat.push_str("[*]"),
                                    '?' => pat.push_str("[?]"),
                                    c => pat.push(c),
                                }
                            }
                        }
                        WFrag::AnyChar => pat.push('?'),
                        WFrag::AnyString => pat.push('*'),
                    }
                }
                match crate::glob::glob(&pat) {
                    Ok(paths) => {
                        if paths.is_empty() {
                            return Err(ExpandError::NoMatches);
                        }
                        out.extend(paths);
                    }
                    Err(e) => {
                        return Err(ExpandError::GlobPanic(format!(
                            "failed to glob: PatternError {{ pos: {}, msg: {:?} }}",
                            e.pos, e.msg
                        )))
                    }
                }
            } else {
                let mut s = String::new();
                for f in &w {
                    match f {
                        WFrag::Lit(l, _) => s.push_str(l),
                        WFrag::AnyChar => s.push('?'),
                        WFrag::AnyString => s.push('*'),
                    }
                }
                out.push(s);
            }
        }
        Ok(out)
    }

    pub fn expand_words(&mut self, words: &[Word]) -> Result<Vec<String>, ExpandError> {
        let mut out = Vec::new();
        for w in words {
            out.extend(self.expand_word_into_vec(w)?);
        }
        Ok(out)
    }

    /// Expands a word into a single string (no globbing; fields are
    /// concatenated).
    pub fn expand_word_into_string(&mut self, word: &Word) -> Result<String, ExpandError> {
        let words = self.expand_word_frags(word)?;
        let mut s = String::new();
        for w in words {
            for f in w {
                match f {
                    WFrag::Lit(l, _) => s.push_str(&l),
                    WFrag::AnyChar => s.push('?'),
                    WFrag::AnyString => s.push('*'),
                }
            }
        }
        Ok(s)
    }

    pub fn expand_into_pattern(&mut self, word: &Word) -> Result<Pattern, ExpandError> {
        let mut frags = Vec::new();
        for span in &word.0 {
            match span {
                Span::Literal(s, _) => {
                    if !s.is_empty() {
                        frags.push(Frag::Lit(s.as_bytes().to_vec()))
                    }
                }
                Span::AnyChar => frags.push(Frag::AnyChar),
                Span::AnyString => frags.push(Frag::AnyString),
                Span::Tilde(user) => {
                    if user.is_some() {
                        self.eprint("nsh: warning: ~user is not yet supported\n");
                    }
                    frags.push(Frag::Lit(self.home.clone().into_bytes()));
                }
                Span::Arith(e) => {
                    let v = self.eval_arith(e);
                    frags.push(Frag::Lit(v.to_string().into_bytes()));
                }
                Span::Param { name, op, index, .. } => {
                    let v = self.expand_param(name, op, index.as_deref())?;
                    let s = v.join("");
                    if !s.is_empty() {
                        frags.push(Frag::Lit(s.into_bytes()));
                    }
                }
                Span::Command { body, .. } => {
                    let s = self.command_substitution(body);
                    if !s.is_empty() {
                        frags.push(Frag::Lit(s.into_bytes()));
                    }
                }
                Span::ProcSubst { body, input } => {
                    if !*input {
                        crate::nsh_panic("src/expand.rs:238:25", "not implemented");
                    }
                    let path = self.run_proc_subst(body);
                    frags.push(Frag::Lit(path.into_bytes()));
                }
            }
        }
        Ok(Pattern { frags })
    }

    fn special_param(&mut self, name: &str) -> Option<Vec<String>> {
        match name {
            "?" => Some(vec![self.last_status.to_string()]),
            "$" => Some(vec![self.pid.to_string()]),
            "!" => Some(vec![self.last_bg_pid.to_string()]),
            "#" => Some(vec![self.args().len().to_string()]),
            "@" => Some(self.args()),
            "*" => Some(vec![self.args().join(" ")]),
            "0" => Some(vec![self.script_name.clone()]),
            _ => None,
        }
    }

    pub fn expand_param(&mut self, name: &str, op: &ExpandOp, index: Option<&Expr>) -> Result<Vec<String>, ExpandError> {
        if let Some(v) = self.special_param(name) {
            return Ok(v);
        }
        let var = self.get_var_value(name);
        let value: Option<String> = match (&var, index) {
            (None, _) => None,
            (Some(Value::String(s)), None) => Some(s.clone()),
            (Some(Value::Array(a)), None) => Some(a.get(0).cloned().unwrap_or_default()),
            (Some(Value::String(_)), Some(_)) => Some(String::new()),
            (Some(Value::Array(a)), Some(e)) => {
                let i = self.eval_arith(e);
                if i < 0 {
                    Some(String::new())
                } else {
                    Some(a.get(i as usize).cloned().unwrap_or_default())
                }
            }
        };
        match op {
            ExpandOp::Length => {
                if index.is_some() {
                    if var.is_none() && self.nounset {
                        return Err(ExpandError::Undefined(name.to_string()));
                    }
                    return Ok(vec![String::new()]);
                }
                match value {
                    Some(v) => Ok(vec![v.chars().count().to_string()]),
                    None => {
                        if self.nounset {
                            return Err(ExpandError::Undefined(name.to_string()));
                        }
                        Ok(vec!["0".to_string()])
                    }
                }
            }
            ExpandOp::GetOrEmpty => match value {
                Some(v) => Ok(vec![v]),
                None => {
                    if self.nounset {
                        return Err(ExpandError::Undefined(name.to_string()));
                    }
                    Ok(vec![String::new()])
                }
            },
            ExpandOp::GetOrDefault(w) => match value {
                Some(v) if !v.is_empty() => Ok(vec![v]),
                _ => Ok(vec![self.expand_word_into_string(w)?]),
            },
            ExpandOp::GetNullableOrDefault(w) => match value {
                Some(v) => Ok(vec![v]),
                None => Ok(vec![self.expand_word_into_string(w)?]),
            },
            ExpandOp::GetOrDefaultAndAssign(w) => match value {
                Some(v) if !v.is_empty() => Ok(vec![v]),
                _ => {
                    let d = self.expand_word_into_string(w)?;
                    self.set_var(name, Value::String(d.clone()));
                    Ok(vec![d])
                }
            },
            ExpandOp::GetNullableOrDefaultAndAssign(w) => match value {
                Some(v) => Ok(vec![v]),
                None => {
                    let d = self.expand_word_into_string(w)?;
                    self.set_var(name, Value::String(d.clone()));
                    Ok(vec![d])
                }
            },
            ExpandOp::Subst { pattern, replacement, global } => {
                let v = match value {
                    Some(v) => v,
                    None => {
                        if self.nounset {
                            return Err(ExpandError::Undefined(name.to_string()));
                        }
                        String::new()
                    }
                };
                let pat = self.expand_into_pattern(pattern)?;
                Ok(vec![pat.replace(&v, replacement, *global)])
            }
        }
    }
}
