            out.extend(self.expand_word_into_vec(w)?);
        }
        Ok(out)
    }

    /// Expands a word into a single string (no globbing; fields are
    /// concatenated).
    pub fn expand_word_into_string(&mut self, word: &Word) -> Result<String, ExpandError> {
        let words = self.expand_word_frags(word)?;
        let mut s = String::new();
        for w in words {
            for f in w {
                match f {
                    WFrag::Lit(l, _) => s.push_str(&l),
                    WFrag::AnyChar => s.push('?'),
                    WFrag::AnyString => s.push('*'),
                }
            }
        }
        Ok(s)
    }

    pub fn expand_into_pattern(&mut self, word: &Word) -> Result<Pattern, ExpandError> {
        let mut frags = Vec::new();
        for span in &word.0 {
            match span {
                Span::Literal(s, _) => {
                    if !s.is_empty() {
                        frags.push(Frag::Lit(s.as_bytes().to_vec()))
                    }
                }
                Span::AnyChar => frags.push(Frag::AnyChar),
                Span::AnyString => frags.push(Frag::AnyString),
                Span::Tilde(user) => {
                    if user.is_some() {
                        self.eprint("nsh: warning: ~user is not yet supported\n");
                    }
                    frags.push(Frag::Lit(self.home.clone().into_bytes()));
                }
                Span::Arith(e) => {
                    let v = self.eval_arith(e);
                    frags.push(Frag::Lit(v.to_string().into_bytes()));
                }
                Span::Param { name, op, index, .. } => {
                    let v = self.expand_param(name, op, index.as_deref())?;
                    let s = v.join("");
                    if !s.is_empty() {
                        frags.push(Frag::Lit(s.into_bytes()));
                    }
                }
                Span::Command { body, .. } => {
                    let s = self.command_substitution(body);
                    if !s.is_empty() {
                        frags.push(Frag::Lit(s.into_bytes()));
                    }
                }
                Span::ProcSubst { body, input } => {
                    if !*input {
                        crate::nsh_panic("src/expand.rs:238:25", "not implemented");
                    }
                    let path = self.run_proc_subst(body);
                    frags.push(Frag::Lit(path.into_bytes()));
                }
            }
        }
        Ok(Pattern { frags })
    }

    fn special_param(&mut self, name: &str) -> Option<Vec<String>> {
        match name {
            "?" => Some(vec![self.last_status.to_string()]),
            "$" => Some(vec![self.pid.to_string()]),
            "!" => Some(vec![self.last_bg_pid.to_string()]),
            "#" => Some(vec![self.args().len().to_string()]),
            "@" => Some(self.args()),
            "*" => Some(vec![self.args().join(" ")]),
            "0" => Some(vec![self.script_name.clone()]),
            _ => None,
        }
    }

    pub fn expand_param(&mut self, name: &str, op: &ExpandOp, index: Option<&Expr>) -> Result<Vec<String>, ExpandError> {
        if let Some(v) = self.special_param(name) {
            return Ok(v);
        }
        let var = self.get_var_value(name);
        let value: Option<String> = match (&var, index) {
            (None, _) => None,
            (Some(Value::String(s)), None) => Some(s.clone()),
            (Some(Value::Array(a)), None) => Some(a.get(0).cloned().unwrap_or_default()),
            (Some(Value::String(_)), Some(_)) => Some(String::new()),
            (Some(Value::Array(a)), Some(e)) => {
                let i = self.eval_arith(e);
                if i < 0 {
                    Some(String::new())
                } else {
                    Some(a.get(i as usize).cloned().unwrap_or_default())
                }
            }
        };
        match op {
            ExpandOp::Length => {
                if index.is_some() {
                    if var.is_none() && self.nounset {
                        return Err(ExpandError::Undefined(name.to_string()));
                    }
                    return Ok(vec![String::new()]);
                }
                match value {
                    Some(v) => Ok(vec![v.chars().count().to_string()]),
                    None => {
                        if self.nounset {
                            return Err(ExpandError::Undefined(name.to_string()));
                        }
                        Ok(vec!["0".to_string()])
                    }
                }
            }
            ExpandOp::GetOrEmpty => match value {
                Some(v) => Ok(vec![v]),
                None => {
                    if self.nounset {
                        return Err(ExpandError::Undefined(name.to_string()));
                    }
                    Ok(vec![String::new()])
                }
            },
            ExpandOp::GetOrDefault(w) => match value {
                Some(v) if !v.is_empty() => Ok(vec![v]),
                _ => Ok(vec![self.expand_word_into_string(w)?]),
            },
            ExpandOp::GetNullableOrDefault(w) => match value {
                Some(v) => Ok(vec![v]),
                None => Ok(vec![self.expand_word_into_string(w)?]),
            },
            ExpandOp::GetOrDefaultAndAssign(w) => match value {
                Some(v) if !v.is_empty() => Ok(vec![v]),
                _ => {
                    let d = self.expand_word_into_string(w)?;
                    self.set_var(name, Value::String(d.clone()));
                    Ok(vec![d])
                }
            },
            ExpandOp::GetNullableOrDefaultAndAssign(w) => match value {
                Some(v) => Ok(vec![v]),
                None => {
                    let d = self.expand_word_into_string(w)?;
                    self.set_var(name, Value::String(d.clone()));
                    Ok(vec![d])
                }
            },
            ExpandOp::Subst { pattern, replacement, global } => {
                let v = match value {
                    Some(v) => v,
                    None => {
                        if self.nounset {
                            return Err(ExpandError::Undefined(name.to_string()));
                        }
                        String::new()
                    }
                };
                let pat = self.expand_into_pattern(pattern)?;
                Ok(vec![pat.replace(&v, replacement, *global)])
            }
        }
    }
}
EOF
