// Shell state and command execution.
use crate::ast::*;
use crate::expand::ExpandError;
use crate::sys;
use std::collections::HashMap;
use std::rc::Rc;

#[derive(Clone, Debug)]
pub enum Value {
    String(String),
    Array(Vec<String>),
}

impl Value {
    pub fn as_str(&self) -> String {
        match self {
            Value::String(s) => s.clone(),
            Value::Array(a) => a.get(0).cloned().unwrap_or_default(),
        }
    }
}

#[derive(Clone, Debug)]
pub struct Variable {
    pub value: Value,
    pub exported: bool,
}

#[derive(Default)]
pub struct Frame {
    pub vars: HashMap<String, Variable>,
    pub args: Vec<String>,
    pub functions: HashMap<String, Rc<Command>>,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Flow {
    Exit(i32),
    Break,
    Continue,
    Return,
}

#[derive(Clone, Copy, Debug)]
pub struct Ctx {
    pub stdin: i32,
    pub stdout: i32,
    pub stderr: i32,
}

pub const DEFAULT_CTX: Ctx = Ctx { stdin: 0, stdout: 1, stderr: 2 };

enum CmdResult {
    Flow(Flow),
    Spawned { pid: i32, external: bool },
}

pub struct Shell {
    pub global: Frame,
    pub frames: Vec<Frame>,
    pub var_order: Vec<String>,
    pub aliases: Vec<(String, String)>,
    pub last_status: i32,
    pub last_bg_pid: i32,
    pub pid: i32,
    pub home: String,
    pub script_name: String,
    pub path_dirs: Vec<String>,
    pub errexit: bool,
    pub nounset: bool,
    pub noexec: bool,
    pub dir_stack: Vec<String>,
    pub prev_dir: Option<String>,
    pub interactive: bool,
    pub heredoc_stack: Vec<Vec<Vec<Vec<Word>>>>,
    pub exported_env: Vec<String>,
}

pub fn status_from_wait(st: i32) -> i32 {
    if sys::wifexited(st) {
        sys::wexitstatus(st)
    } else {
        -1
    }
}

pub fn waitpid_blocking(pid: i32) -> i32 {
    let mut st: i32 = 0;
    loop {
        let r = unsafe { sys::waitpid(pid, &mut st, 0) };
        if r < 0 {
            if sys::errno() == 4 {
                continue;
            }
            return 0;
        }
        return status_from_wait(st);
    }
}

impl Shell {
    pub fn new() -> Shell {
        let home = home_dir();
        let mut sh = Shell {
            global: Frame::default(),
            frames: Vec::new(),
            var_order: Vec::new(),
            aliases: Vec::new(),
            last_status: 0,
            last_bg_pid: 0,
            pid: unsafe { sys::getpid() },
            home,
            script_name: String::new(),
            path_dirs: Vec::new(),
            errexit: false,
            nounset: false,
            noexec: false,
            dir_stack: Vec::new(),
            prev_dir: None,
            interactive: false,
            heredoc_stack: Vec::new(),
            exported_env: Vec::new(),
        };
        for (k, v) in std::env::vars_os() {
            let k = k.to_string_lossy().into_owned();
            let v = v.to_string_lossy().into_owned();
            sh.global.vars.insert(k, Variable { value: Value::String(v), exported: false });
        }
        let path = std::env::var("PATH").unwrap_or_default();
        sh.set_path(&path);
        sh
    }

    pub fn set_path(&mut self, path: &str) {
        self.path_dirs = path.split(':').map(|s| s.to_string()).collect();
    }

    // ---------------- output helpers ----------------
    pub fn eprint(&self, s: &str) {
        let _ = sys::write_all(2, s.as_bytes());
    }

    pub fn write_fd(&self, fd: i32, s: &[u8]) {
        if let Err(e) = sys::write_all(fd, s) {
            if e == 32 {
                // broken pipe: ignore
                return;
            }
            crate::nsh_panic("src/utils.rs:51:47", &format!("failed to write: {}", sys::errno_name(e)));
        }
    }

    // ---------------- variables ----------------
    fn cur_frame(&self) -> Option<&Frame> {
        self.frames.last()
    }

    pub fn in_function(&self) -> bool {
        !self.frames.is_empty()
    }

    pub fn args(&self) -> Vec<String> {
        match self.cur_frame() {
            Some(f) => f.args.clone(),
            None => self.global.args.clone(),
        }
    }

    pub fn set_args(&mut self, args: Vec<String>) {
        match self.frames.last_mut() {
            Some(f) => f.args = args,
            None => self.global.args = args,
        }
    }

    pub fn get_var_value(&self, name: &str) -> Option<Value> {
        if let Some(f) = self.cur_frame() {
            if let Some(v) = f.vars.get(name) {
                return Some(v.value.clone());
            }
        }
        if let Some(v) = self.global.vars.get(name) {
            return Some(v.value.clone());
        }
        // positional parameters
        if !name.is_empty() && name.bytes().all(|b| b.is_ascii_digit()) {
            if let Ok(n) = name.parse::<usize>() {
                if n >= 1 {
                    let args = self.args();
                    if let Some(a) = args.get(n - 1) {
                        return Some(Value::String(a.clone()));
                    }
                }
            }
        }
        None
    }

    pub fn get_var_str(&self, name: &str) -> Option<String> {
        self.get_var_value(name).map(|v| v.as_str())
    }

    pub fn set_var(&mut self, name: &str, value: Value) {
        if let Some(f) = self.frames.last_mut() {
            if let Some(v) = f.vars.get_mut(name) {
                v.value = value;
                return;
            }
        }
        match self.global.vars.get_mut(name) {
            Some(v) => v.value = value,
            None => {
                self.global.vars.insert(name.to_string(), Variable { value, exported: false });
            }
        }
    }

    pub fn set_local(&mut self, name: &str, value: Value) {
        if let Some(f) = self.frames.last_mut() {
            match f.vars.get_mut(name) {
                Some(v) => v.value = value,
                None => {
                    f.vars.insert(name.to_string(), Variable { value, exported: false });
                }
            }
        }
    }

    pub fn export_var(&mut self, name: &str) {
        let mut found = false;
        if let Some(f) = self.frames.last_mut() {
            if let Some(v) = f.vars.get_mut(name) {
                v.exported = true;
                found = true;
            }
        }
        if !found {
            if let Some(v) = self.global.vars.get_mut(name) {
                v.exported = true;
                found = true;
            }
        }
        if found && !self.exported_env.iter().any(|n| n == name) {
            self.exported_env.push(name.to_string());
        }
    }

    pub fn unset_var(&mut self, name: &str) {
        if let Some(f) = self.frames.last_mut() {
            if f.vars.remove(name).is_some() {
                return;
            }
        }
        self.global.vars.remove(name);
    }

    pub fn lookup_function(&self, name: &str) -> Option<Rc<Command>> {
        if let Some(f) = self.cur_frame() {
            if let Some(c) = f.functions.get(name) {
                return Some(c.clone());
            }
        }
        self.global.functions.get(name).cloned()
    }

    pub fn unset_function(&mut self, name: &str) {
        if let Some(f) = self.frames.last_mut() {
            if f.functions.remove(name).is_some() {
                return;
            }
        }
        self.global.functions.remove(name);
    }

    pub fn exported_vars(&self) -> Vec<(String, String)> {
        let mut out = Vec::new();
        for name in &self.exported_env {
            let v = if let Some(f) = self.cur_frame() {
                f.vars.get(name).filter(|v| v.exported).or_else(|| self.global.vars.get(name).filter(|v| v.exported))
            } else {
                self.global.vars.get(name).filter(|v| v.exported)
            };
            if let Some(v) = v {
                out.push((name.clone(), v.value.as_str()));
            }
        }
        out
    }

    // ---------------- running scripts ----------------

    pub fn run_script(&mut self, script: &str) -> i32 {
        match crate::parser::parse(script) {
            Ok(ast) => {
                self.heredoc_stack.push(ast.heredocs.clone());
                let flow = self.run_terms(&ast.terms, DEFAULT_CTX);
                self.heredoc_stack.pop();
                match flow {
                    Flow::Exit(n) => n,
                    Flow::Break => crate::nsh_panic("src/main.rs:133:14", "unexpected Break"),
                    Flow::Continue => crate::nsh_panic("src/main.rs:133:14", "unexpected Continue"),
                    Flow::Return => crate::nsh_panic("src/main.rs:133:14", "unexpected Return"),
                }
            }
            Err(crate::parser::ParseError::Empty) => self.last_status,
            Err(crate::parser::ParseError::Fatal(msg)) => {
                self.eprint(&format!("nsh: parse error: {}\n", msg));
                -1
            }
        }
    }

    /// Runs a script within the current context (eval/source). Returns flow.
    pub fn run_script_flow(&mut self, script: &str, ctx: Ctx) -> Flow {
        match crate::parser::parse(script) {
            Ok(ast) => {
                self.heredoc_stack.push(ast.heredocs.clone());
                let flow = self.run_terms(&ast.terms, ctx);
                self.heredoc_stack.pop();
                flow
            }
            Err(crate::parser::ParseError::Empty) => Flow::Exit(self.last_status),
            Err(crate::parser::ParseError::Fatal(msg)) => {
                self.eprint(&format!("nsh: parse error: {}\n", msg));
                Flow::Exit(-1)
            }
        }
    }

    pub fn run_terms(&mut self, terms: &[Term], ctx: Ctx) -> Flow {
        for term in terms {
            if self.noexec {
                break;
            }
            let flow = self.run_term(term, ctx);
            match flow {
                Flow::Exit(n) => self.last_status = n,
                other => return other,
            }
            if self.errexit && self.last_status != 0 {
                crate::exit_shell(self.last_status);
            }
        }
        Flow::Exit(self.last_status)
    }

    fn run_term(&mut self, term: &Term, ctx: Ctx) -> Flow {
        let mut flow = Flow::Exit(self.last_status);
        for (run_if, pipeline) in &term.pipelines {
            if *run_if == RunIf::Success && self.last_status != 0 {
                continue;
            }
            flow = self.run_pipeline(pipeline, ctx, term.background, &term.code);
            match flow {
                Flow::Exit(n) => self.last_status = n,
                _ => return flow,
            }
        }
        flow
    }

    fn run_pipeline(&mut self, p: &Pipeline, ctx: Ctx, background: bool, code: &str) -> Flow {
        if p.commands.is_empty() {
            return Flow::Exit(self.last_status);
        }
        let n = p.commands.len();
        let mut stdin = ctx.stdin;
        let mut children: Vec<(i32, bool)> = Vec::new();
        let mut last: Option<CmdResult> = None;
        for (i, cmd) in p.commands.iter().enumerate() {
            let (stdout, next_stdin) = if i + 1 < n {
                let (r, w) = make_pipe();
                (w, Some(r))
            } else {
                (ctx.stdout, None)
            };
            let c = Ctx { stdin, stdout, stderr: ctx.stderr };
            let r = self.run_command(cmd, c, next_stdin);
            if stdout != ctx.stdout {
                unsafe { sys::close(stdout) };
            }
            if stdin != ctx.stdin {
                unsafe { sys::close(stdin) };
            }
            if let Some(ns) = next_stdin {
                stdin = ns;
            }
            match r {
                CmdResult::Spawned { pid, external } => {
                    children.push((pid, external));
                    last = Some(CmdResult::Spawned { pid, external });
                }
                CmdResult::Flow(f) => {
                    match f {
                        Flow::Exit(_) => {}
                        other => {
                            // wait for already spawned children
                            for (pid, _) in &children {
                                waitpid_blocking(*pid);
                            }
                            return other;
                        }
                    }
                    last = Some(CmdResult::Flow(f));
                }
            }
        }
        let mut status = 0;
        let last_pid = match &last {
            Some(CmdResult::Spawned { pid, .. }) => Some(*pid),
            _ => None,
        };
        let mut any_external = false;
        for (pid, external) in &children {
            let st = waitpid_blocking(*pid);
            if *external {
                any_external = true;
            }
            if Some(*pid) == last_pid {
                status = st;
            }
        }
        if let Some(CmdResult::Flow(Flow::Exit(n))) = last {
            status = n;
        }
        if background && any_external {
            self.write_fd(1, format!("[1] Done: {}\n", code).as_bytes());
        }
        Flow::Exit(status)
    }

    fn run_command(&mut self, cmd: &Command, ctx: Ctx, close_in_child: Option<i32>) -> CmdResult {
        match cmd {
            Command::SimpleCommand { argv, redirects, assignments } => {
                self.run_simple_command(argv, redirects, assignments, ctx, close_in_child)
            }
            Command::Empty => CmdResult::Flow(Flow::Exit(self.last_status)),
            Command::If { condition, then_part, elif_parts, else_part } => {
                let f = self.run_terms(condition, ctx);
                match f {
                    Flow::Exit(0) => return CmdResult::Flow(self.run_terms(then_part, ctx)),
                    Flow::Exit(_) => {}
                    other => return CmdResult::Flow(other),
                }
                for elif in elif_parts {
                    let f = self.run_terms(&elif.condition, ctx);
                    match f {
                        Flow::Exit(0) => return CmdResult::Flow(self.run_terms(then_part, ctx)),
                        Flow::Exit(_) => {}
                        other => return CmdResult::Flow(other),
                    }
                }
                if let Some(e) = else_part {
                    return CmdResult::Flow(self.run_terms(e, ctx));
                }
                CmdResult::Flow(Flow::Exit(0))
            }
            Command::While { condition, body } => {
                let mut result = Flow::Exit(0);
                loop {
                    let f = self.run_terms(condition, ctx);
                    match f {
                        Flow::Exit(0) => {}
                        Flow::Exit(_) => break,
                        other => return CmdResult::Flow(other),
                    }
                    result = self.run_terms(body, ctx);
                    if let Flow::Return = result {
                        // keep looping (quirk)
                    }
                }
                CmdResult::Flow(result)
            }
            Command::For { var_name, words, body } => {
                let values = match self.expand_words(words) {
                    Ok(v) => v,
                    Err(e) => return CmdResult::Flow(Flow::Exit(self.report_expand_error(e))),
                };
                for v in values {
                    self.set_var(var_name, Value::String(v));
                    match self.run_terms(body, ctx) {
                        Flow::Break => break,
                        Flow::Continue => continue,
                        Flow::Return => return CmdResult::Flow(Flow::Return),
                        Flow::Exit(_) => {}
                    }
                }
                CmdResult::Flow(Flow::Exit(0))
            }
            Command::ArithFor { init, cond, update, body } => {
                self.eval_arith(init);
                loop {
                    if self.eval_arith(cond) == 0 {
                        break;
                    }
                    match self.run_terms(body, ctx) {
                        Flow::Break => break,
                        Flow::Continue => {}
                        Flow::Return => return CmdResult::Flow(Flow::Return),
                        Flow::Exit(_) => {}
                    }
                    self.eval_arith(update);
                }
                CmdResult::Flow(Flow::Exit(0))
            }
            Command::Case { word, items } => {
                let w = match self.expand_word_into_string(word) {
                    Ok(w) => w,
                    Err(e) => return CmdResult::Flow(Flow::Exit(self.report_expand_error(e))),
                };
                for item in items {
                    for pat in &item.patterns {
                        let p = match self.expand_into_pattern(pat) {
                            Ok(p) => p,
                            Err(e) => return CmdResult::Flow(Flow::Exit(self.report_expand_error(e))),
                        };
                        if p.contains_match(&w) {
                            return CmdResult::Flow(self.run_terms(&item.body, ctx));
                        }
                    }
                }
                CmdResult::Flow(Flow::Exit(0))
            }
            Command::FunctionDef { name, body } => {
                let f = Rc::new((**body).clone());
                match self.frames.last_mut() {
                    Some(fr) => {
                        fr.functions.insert(name.clone(), f);
                    }
                    None => {
                        self.global.functions.insert(name.clone(), f);
                    }
                }
                CmdResult::Flow(Flow::Exit(0))
            }
            Command::Group { terms } => CmdResult::Flow(self.run_terms(terms, ctx)),
            Command::SubShell { terms } => {
                let pid = unsafe { sys::fork() };
                if pid == 0 {
                    if let Some(fd) = close_in_child {
                        unsafe { sys::close(fd) };
                    }
                    let f = self.run_terms(terms, ctx);
                    let code = match f {
                        Flow::Exit(n) => n,
                        _ => 0,
                    };
                    crate::exit_shell(code);
                }
                CmdResult::Spawned { pid, external: false }
            }
            Command::Cond(e) => {
                let r = match self.eval_cond(e) {
                    Ok(b) => b,
                    Err(err) => return CmdResult::Flow(Flow::Exit(self.report_expand_error(err))),
                };
                CmdResult::Flow(Flow::Exit(if r { 0 } else { 1 }))
            }
            Command::Assignment { assignments } => {
                for a in assignments {
                    match self.eval_initializer(&a.initializer) {
                        Ok(v) => self.set_var(&a.name, v),
                        Err(e) => return CmdResult::Flow(Flow::Exit(self.report_expand_error(e))),
                    }
                }
                CmdResult::Flow(Flow::Exit(0))
            }
            Command::LocalDef { declarations } => {
                if !self.in_function() {
                    self.eprint("nsh: local variable can only be used in a function\n");
                    return CmdResult::Flow(Flow::Exit(1));
                }
                for d in declarations {
                    let v = match &d.initializer {
                        Some(init) => match self.eval_initializer(init) {
                            Ok(v) => v,
                            Err(e) => return CmdResult::Flow(Flow::Exit(self.report_expand_error(e))),
                        },
                        None => Value::String(String::new()),
                    };
                    self.set_local(&d.name, v);
                }
                CmdResult::Flow(Flow::Exit(0))
            }
            Command::Return { .. } => CmdResult::Flow(Flow::Return),
            Command::Break => CmdResult::Flow(Flow::Break),
            Command::Continue => CmdResult::Flow(Flow::Continue),
        }
    }

    pub fn eval_initializer(&mut self, init: &Initializer) -> Result<Value, ExpandError> {
        match init {
            Initializer::String(w) => Ok(Value::String(self.expand_word_into_string(w)?)),
            Initializer::Array(ws) => Ok(Value::Array(self.expand_words(ws)?)),
        }
    }

    pub fn report_expand_error(&mut self, e: ExpandError) -> i32 {
        match e {
            ExpandError::NoMatches => {
                self.eprint("nsh: error: no matches\n");
                1
            }
            ExpandError::Undefined(name) => {
                self.eprint(&format!("nsh: undefined variable `{}'\n", name));
                crate::exit_shell(1);
            }
            ExpandError::GlobPanic(msg) => crate::nsh_panic("src/pattern.rs:73:41", &msg),
        }
    }

    // ---------------- simple commands ----------------

    fn alias_expand(&self, word: &Word) -> Option<Vec<String>> {
        if self.aliases.is_empty() {
            return None;
        }
        let mut name = String::new();
        for s in &word.0 {
            match s {
                Span::Literal(l, _) => name.push_str(l),
                _ => return None,
            }
        }
        for (n, v) in &self.aliases {
            if *n == name {
                let t = v.trim();
                return Some(t.split(' ').map(|s| s.to_string()).collect());
            }
        }
        None
    }

    fn run_simple_command(
        &mut self,
        argv_words: &[Word],
        redirects: &[Redirection],
        assignments: &[Assignment],
        ctx: Ctx,
        close_in_child: Option<i32>,
    ) -> CmdResult {
        let alias = argv_words.get(0).and_then(|w| self.alias_expand(w));
        let mut argv = Vec::new();
        let rest_start = if alias.is_some() { 1 } else { 0 };
        if let Some(a) = alias {
            argv.extend(a);
        }
        for w in &argv_words[rest_start..] {
            match self.expand_word_into_vec(w) {
                Ok(v) => argv.extend(v),
                Err(e) => return CmdResult::Flow(Flow::Exit(self.report_expand_error(e))),
            }
        }
        if argv.is_empty() {
            return CmdResult::Flow(Flow::Exit(0));
        }
        // functions
        if let Some(func) = self.lookup_function(&argv[0]) {
            return CmdResult::Flow(self.call_function(func, &argv, ctx));
        }
        // builtins
        if crate::builtins::is_builtin(&argv[0]) {
            let mut bctx = ctx;
            let mut opened = Vec::new();
            match self.setup_builtin_redirects(redirects, &mut bctx, &mut opened) {
                Ok(()) => {}
                Err(()) => {
                    for fd in opened {
                        unsafe { sys::close(fd) };
                    }
                    return CmdResult::Flow(Flow::Exit(1));
                }
            }
            let f = crate::builtins::run(self, &argv, bctx);
            for fd in opened {
                unsafe { sys::close(fd) };
            }
            return CmdResult::Flow(f);
        }
        // external
        let mut env = Vec::new();
        for a in assignments {
            match self.eval_initializer(&a.initializer) {
                Ok(v) => env.push((a.name.clone(), v.as_str())),
                Err(e) => return CmdResult::Flow(Flow::Exit(self.report_expand_error(e))),
            }
        }
        let path = match self.lookup_external(&argv[0]) {
            Some(p) => p,
            None => {
                self.eprint(&format!("nsh: command not found `{}'\n", argv[0]));
                return CmdResult::Flow(Flow::Exit(1));
            }
        };
        // open redirection files in the parent
        let mut prepared: Vec<(i32, PreparedTarget)> = Vec::new();
        for r in redirects {
            match self.prepare_redirect(r) {
                Ok(t) => prepared.push((r.fd, t)),
                Err(()) => {
                    for (_, t) in prepared {
                        if let PreparedTarget::Opened(fd) = t {
                            unsafe { sys::close(fd) };
                        }
                    }
                    return CmdResult::Flow(Flow::Exit(1));
                }
            }
        }
        let exported = self.exported_vars();
        let pid = unsafe { sys::fork() };
        if pid == 0 {
            if let Some(fd) = close_in_child {
                unsafe { sys::close(fd) };
            }
            let mut redirected = [false; 3];
            for (fd, t) in &prepared {
                let src = match t {
                    PreparedTarget::Opened(f) => *f,
                    PreparedTarget::Fd(f) => *f,
                };
                if unsafe { sys::dup2(src, *fd) } < 0 {
                    crate::nsh_panic("src/process.rs:30:24", &format!("failed to dup2: {}", sys::errno_name(sys::errno())));
                }
                if *fd >= 0 && *fd < 3 {
                    redirected[*fd as usize] = true;
                }
            }
            let fds = [ctx.stdin, ctx.stdout, ctx.stderr];
            for i in 0..3 {
                if !redirected[i] && fds[i] != i as i32 {
                    unsafe { sys::dup2(fds[i], i as i32) };
                }
            }
            for (k, v) in exported {
                std::env::set_var(k, v);
            }
            for (k, v) in env {
                std::env::set_var(k, v);
            }
            exec_or_die(&path, &argv);
        }
        for (_, t) in prepared {
            if let PreparedTarget::Opened(fd) = t {
                unsafe { sys::close(fd) };
            }
        }
        CmdResult::Spawned { pid, external: true }
    }

    pub fn lookup_external(&self, name: &str) -> Option<String> {
        if name.contains('/') {
            return Some(name.to_string());
        }
        if name.is_empty() {
            return None;
        }
        for d in &self.path_dirs {
            let p = format!("{}/{}", d, name);
            if let Ok(m) = std::fs::metadata(&p) {
                if m.is_file() {
                    return Some(p);
                }
            }
        }
        None
    }

    fn heredoc_content(&mut self, lines: &[Vec<Word>]) -> String {
        let mut out_lines = Vec::new();
        for line in lines {
            let mut ws = Vec::new();
            for w in line {
                match self.expand_word_into_string(w) {
                    Ok(s) => ws.push(s),
                    Err(e) => {
                        self.report_expand_error(e);
                    }
                }
            }
            out_lines.push(ws.join(" "));
        }
        let mut s = out_lines.join("\n");
        s.push('\n');
        s
    }

    fn prepare_redirect(&mut self, r: &Redirection) -> Result<PreparedTarget, ()> {
        match &r.target {
            RedirectionTarget::Fd(n) => Ok(PreparedTarget::Fd(*n)),
            RedirectionTarget::HereDoc(_) => {
                crate::nsh_panic("src/process.rs:367:17", "internal error: entered unreachable code")
            }
            RedirectionTarget::HereDocBody(lines) => {
                let content = self.heredoc_content(lines);
                let (r, w) = make_pipe();
                let _ = sys::write_all(w, content.as_bytes());
                unsafe { sys::close(w) };
                Ok(PreparedTarget::Opened(r))
            }
            RedirectionTarget::File(word) => {
                let path = match self.expand_word_into_string(word) {
                    Ok(p) => p,
                    Err(e) => {
                        self.report_expand_error(e);
                        return Err(());
                    }
                };
                let flags = match r.direction {
                    RedirectionDirection::Input => sys::O_RDONLY,
                    RedirectionDirection::Output => sys::O_WRONLY | sys::O_CREAT,
                    RedirectionDirection::Append => sys::O_WRONLY | sys::O_CREAT | sys::O_APPEND,
                };
                let c = sys::cstr(&path);
                let fd = unsafe { sys::open(c.as_ptr(), flags | sys::O_CLOEXEC, 0o644) };
                if fd < 0 {
                    return Err(());
                }
                Ok(PreparedTarget::Opened(fd))
            }
        }
    }

    fn setup_builtin_redirects(&mut self, redirects: &[Redirection], ctx: &mut Ctx, opened: &mut Vec<i32>) -> Result<(), ()> {
        for r in redirects {
            let fd = match self.prepare_redirect(r)? {
                PreparedTarget::Opened(fd) => {
                    opened.push(fd);
                    fd
                }
                PreparedTarget::Fd(fd) => fd,
            };
            match r.fd {
                0 => ctx.stdin = fd,
                1 => ctx.stdout = fd,
                2 => ctx.stderr = fd,
                _ => {}
            }
        }
        Ok(())
    }

    pub fn call_function(&mut self, func: Rc<Command>, argv: &[String], ctx: Ctx) -> Flow {
        let mut frame = Frame::default();
        frame.args = argv[1..].to_vec();
        for (i, a) in argv[1..].iter().enumerate() {
            frame.vars.insert((i + 1).to_string(), Variable { value: Value::String(a.clone()), exported: false });
        }
        self.frames.push(frame);
        let r = self.run_command(&func, ctx, None);
        let flow = match r {
            CmdResult::Flow(f) => f,
            CmdResult::Spawned { pid, .. } => Flow::Exit(waitpid_blocking(pid)),
        };
        self.frames.pop();
        match flow {
            Flow::Return => Flow::Exit(0),
            other => other,
        }
    }

    // ---------------- substitutions ----------------

    pub fn command_substitution(&mut self, body: &[Term]) -> String {
        let (r, w) = make_pipe();
        let pid = unsafe { sys::fork() };
        if pid == 0 {
            unsafe { sys::close(r) };
            let ctx = Ctx { stdin: 0, stdout: w, stderr: 2 };
            let f = self.run_terms(body, ctx);
            let code = match f {
                Flow::Exit(n) => n,
                _ => 0,
            };
            crate::exit_shell(code);
        }
        unsafe { sys::close(w) };
        let mut out = Vec::new();
        let mut buf = [0u8; 4096];
        loop {
            let n = unsafe { sys::read(r, buf.as_mut_ptr() as *mut _, buf.len()) };
            if n < 0 {
                if sys::errno() == 4 {
                    continue;
                }
                break;
            }
            if n == 0 {
                break;
            }
            out.extend_from_slice(&buf[..n as usize]);
        }
        unsafe { sys::close(r) };
        waitpid_blocking(pid);
        while out.last() == Some(&b'\n') {
            out.pop();
        }
        String::from_utf8_lossy(&out).into_owned()
    }

    pub fn run_proc_subst(&mut self, body: &[Term]) -> String {
        let mut fds = [0i32; 2];
        unsafe { sys::pipe(fds.as_mut_ptr()) };
        let (r, w) = (fds[0], fds[1]);
        let pid = unsafe { sys::fork() };
        if pid == 0 {
            unsafe { sys::close(r) };
            let ctx = Ctx { stdin: 0, stdout: w, stderr: 2 };
            let f = self.run_terms(body, ctx);
            let code = match f {
                Flow::Exit(n) => n,
                _ => 0,
            };
            crate::exit_shell(code);
        }
        unsafe { sys::close(w) };
        format!("/dev/fd/{}", r)
    }

    // ---------------- arithmetic ----------------

    pub fn eval_arith(&mut self, e: &Expr) -> i32 {
        match e {
            Expr::Num(n) => *n,
            Expr::Var(name) => self.arith_var(name),
            Expr::Paren(e) => self.eval_arith(e),
            Expr::Add(a, b) => {
                let x = self.eval_arith(a);
                let y = self.eval_arith(b);
                x.wrapping_add(y)
            }
            Expr::Sub(a, b) => {
                let x = self.eval_arith(a);
                let y = self.eval_arith(b);
                x.wrapping_sub(y)
            }
            Expr::Mul(a, b) => {
                let x = self.eval_arith(a);
                let y = self.eval_arith(b);
                x.wrapping_mul(y)
            }
            Expr::Div(a, b) => {
                let x = self.eval_arith(a);
                let y = self.eval_arith(b);
                if y == 0 {
                    crate::nsh_panic("src/eval.rs:38:47", "attempt to divide by zero");
                }
                if x == i32::MIN && y == -1 {
                    crate::nsh_panic("src/eval.rs:38:47", "attempt to divide with overflow");
                }
                x / y
            }
            Expr::Assign(name, e) => {
                let v = self.eval_arith(e);
                self.set_var(name, Value::String(v.to_string()));
                v
            }
            Expr::Eq(a, b) => (self.eval_arith(a) == self.eval_arith(b)) as i32,
            Expr::Ne(a, b) => (self.eval_arith(a) != self.eval_arith(b)) as i32,
            Expr::Lt(a, b) => (self.eval_arith(a) < self.eval_arith(b)) as i32,
            Expr::Le(a, b) => (self.eval_arith(a) <= self.eval_arith(b)) as i32,
            Expr::Gt(a, b) => (self.eval_arith(a) > self.eval_arith(b)) as i32,
            Expr::Ge(a, b) => (self.eval_arith(a) >= self.eval_arith(b)) as i32,
            Expr::Inc(name) => {
                let v = self.arith_var(name).wrapping_add(1);
                self.set_var(name, Value::String(v.to_string()));
                v
            }
            Expr::Dec(name) => {
                let v = self.arith_var(name).wrapping_sub(1);
                self.set_var(name, Value::String(v.to_string()));
                v
            }
        }
    }

    fn arith_var(&self, name: &str) -> i32 {
        match self.get_var_value(name) {
            Some(Value::String(s)) => s.parse::<i32>().unwrap_or(0),
            _ => 0,
        }
    }

    // ---------------- [[ ]] ----------------

    fn cond_word(&mut self, e: &CondExpr) -> Result<String, ExpandError> {
        match e {
            CondExpr::Word(w) => self.expand_word_into_string(w),
            _ => crate::nsh_panic("src/eval.rs:541:17", "internal error: entered unreachable code"),
        }
    }

    fn cond_int(&mut self, e: &CondExpr) -> Result<i32, ExpandError> {
        let s = self.cond_word(e)?;
        Ok(s.parse::<i32>().unwrap_or(0))
    }

    pub fn eval_cond(&mut self, e: &CondExpr) -> Result<bool, ExpandError> {
        Ok(match e {
            CondExpr::Word(_) => true,
            CondExpr::Or(a, b) => self.eval_cond(a)? || self.eval_cond(b)?,
            CondExpr::And(a, b) => self.eval_cond(a)? && self.eval_cond(b)?,
            CondExpr::StrEq(a, b) | CondExpr::StrNe(a, b) => {
                let lhs = self.cond_word(a)?;
                let pat = match &**b {
                    CondExpr::Word(w) => self.expand_into_pattern(w)?,
                    _ => crate::nsh_panic("src/eval.rs:541:17", "internal error: entered unreachable code"),
                };
                let m = pat.is_match(&lhs);
                if let CondExpr::StrEq(..) = e {
                    m
                } else {
                    !m
                }
            }
            CondExpr::Eq(a, b) => self.cond_int(a)? == self.cond_int(b)?,
            CondExpr::Ne(a, b) => self.cond_int(a)? != self.cond_int(b)?,
            CondExpr::Lt(a, b) => self.cond_int(a)? < self.cond_int(b)?,
            CondExpr::Le(a, b) => self.cond_int(a)? <= self.cond_int(b)?,
            CondExpr::Gt(a, b) => self.cond_int(a)? > self.cond_int(b)?,
            CondExpr::Ge(a, b) => self.cond_int(a)? >= self.cond_int(b)?,
        })
    }
}

pub enum PreparedTarget {
    Opened(i32),
    Fd(i32),
}

pub fn make_pipe() -> (i32, i32) {
    let mut fds = [0i32; 2];
    unsafe {
        sys::pipe(fds.as_mut_ptr());
        sys::fcntl(fds[0], sys::F_SETFD, sys::FD_CLOEXEC);
        sys::fcntl(fds[1], sys::F_SETFD, sys::FD_CLOEXEC);
    }
    (fds[0], fds[1])
}

pub fn exec_or_die(path: &str, argv: &[String]) -> ! {
    let cpath = sys::cstr(path);
    let cargs: Vec<std::ffi::CString> = argv.iter().map(|a| sys::cstr(a)).collect();
    let mut ptrs: Vec<*const std::os::raw::c_char> = cargs.iter().map(|c| c.as_ptr()).collect();
    ptrs.push(std::ptr::null());
    unsafe { sys::execv(cpath.as_ptr(), ptrs.as_ptr()) };
    let e = sys::errno();
    let msg = match e {
        13 => format!("nsh: Failed to exec \"{}\" (EACCESS). chmod(1) may help.\n", path),
        _ => format!("nsh: Failed to exec \"{}\" ({}: {})\n", path, sys::errno_name(e), sys::errno_desc(e)),
    };
    let _ = sys::write_all(2, msg.as_bytes());
    unsafe { sys::_exit(1) }
}

pub fn home_dir() -> String {
    if let Ok(h) = std::env::var("HOME") {
        if !h.is_empty() {
            return h;
        }
    }
    unsafe {
        let pw = sys::getpwuid(sys::getuid());
        if !pw.is_null() && !(*pw).pw_dir.is_null() {
            return std::ffi::CStr::from_ptr((*pw).pw_dir).to_string_lossy().into_owned();
        }
    }
    String::new()
}
