    let mut newline = true;
    let mut escape = false;
    if let Some(first) = args.get(0) {
        match first.as_str() {
            "-n" => {
                newline = false;
                args = &args[1..];
            }
            "-e" => {
                escape = true;
                args = &args[1..];
            }
            "-ne" | "-en" => {
                newline = false;
                escape = true;
                args = &args[1..];
            }
            _ => {}
        }
    }
    let mut out = args.join(" ");
    if escape {
