fn exec(sh: &mut Shell, argv: &[String]) -> Flow {
    if argv.len() < 2 {
        return Flow::Exit(0);
    }
    let path = match sh.lookup_external(&argv[1]) {
        Some(p) => p,
        None => argv[1].clone(),
    };
    for (k, v) in sh.exported_vars() {
        std::env::set_var(k, v);
    }
    let cpath = sys::cstr(&path);
