                }
            }
            None => sh.export_var(a),
        }
    }
    Flow::Exit(0)
}

fn read(sh: &mut Shell, argv: &[String], ctx: Ctx) -> Flow {
    match clap_parse(sh, &clap::READ, "read: ", argv) {
