                if b[0] == b'\n' {
                    break;
                }
                line.push(b[0]);
            }
            if !got_any {
                return Flow::Exit(1);
            }
            let s = String::from_utf8_lossy(&line).trim_end().to_string();
            sh.set_var(&var, Value::String(s));
            Flow::Exit(0)
        }
        Ok(_) => Flow::Exit(1),
        Err(f) => f,
    }
}

fn source(sh: &mut Shell, argv: &[String], ctx: Ctx) -> Flow {
