        let a = args[i].clone();
        i += 1;
        if !only_pos && a == "--" {
            only_pos = true;
            continue;
        }
        if !only_pos && a.starts_with("--") {
            match a.as_str() {
                "--help" => print_help(&bin),
                "--version" => {
                    let _ = sys::write_all(1, b"0.4.2\n");
                    exit_shell(0);
                }
                "--login" => o.login = true,
                "--norc" => o.norc = true,
                _ => found(&a),
            }
            continue;
        }
