                let c = chars[j];
                j += 1;
                match c {
                    'h' => print_help(&bin),
                    'l' => o.login = true,
                    'c' => {
                        let rest: String = chars[j..].iter().collect();
                        let val = if !rest.is_empty() {
                            Some(rest)
                        } else if i < args.len() {
                            i += 1;
                            Some(args[i - 1].clone())
                        } else {
                            None
                        };
                        match val {
                            Some(v) => {
                                if o.command.is_some() {
                                    usage_error(&format!("error: The argument '-c <command>' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} -c <command>\n\nFor more information try --help\n", bin));
                                }
                                o.command = Some(v);
                            }
