    if !opts.norc {
        load_nshrc(&mut sh);
    }
    if let Some(cmd) = opts.command {
        let st = sh.run_script(&cmd);
        exit_shell(st);
    }
    if let Some(file) = opts.file {
        sh.script_name = file.clone();
        let content = match std::fs::read_to_string(&file) {
            Ok(c) => c,
            Err(e) => {
                sh.eprint(&format!("nsh: failed to open the file: {:?}\n", e));
                exit_shell(1);
            }
        };
        let st = sh.run_script(&content);
        exit_shell(st);
    }
    let st = interactive::run(&mut sh);
    exit_shell(st);
}
