// Pattern matching used by `case`, `[[ == ]]` and `${x/pat/rep}`.
// The matcher works on bytes (like the original implementation).

#[derive(Debug, Clone)]
pub enum Frag {
    Lit(Vec<u8>),
    AnyChar,
    AnyString,
}

#[derive(Debug, Clone)]
pub struct Pattern {
    pub frags: Vec<Frag>,
}

fn check_boundary(text: &str, pos: usize, loc: &str) {
    if pos <= text.len() && !text.is_char_boundary(pos) {
        let mut start = pos;
        while !text.is_char_boundary(start) {
            start -= 1;
        }
        let c = text[start..].chars().next().unwrap();
        let end = start + c.len_utf8();
        crate::nsh_panic(
            loc,
            &format!(
                "byte index {} is not a char boundary; it is inside {:?} (bytes {}..{}) of `{}`",
                pos, c, start, end, text
            ),
        );
    }
}

fn longest(frags: &[Frag], text: &str, pos: usize) -> Option<usize> {
    check_boundary(text, pos, "src/pattern.rs:123:15");
    let t = text.as_bytes();
    match frags.first() {
        None => Some(pos),
        Some(Frag::Lit(l)) => {
            if t[pos..].starts_with(l) {
                let n = String::from_utf8_lossy(l).chars().count();
                longest(&frags[1..], text, pos + n)
            } else {
                None
            }
        }
        Some(Frag::AnyChar) => {
            if pos < t.len() {
                longest(&frags[1..], text, pos + 1)
            } else {
                None
            }
        }
        Some(Frag::AnyString) => {
            let mut end = t.len();
            loop {
                if let Some(e) = longest(&frags[1..], text, end) {
                    return Some(e);
                }
                if end == pos {
                    return None;
                }
                end -= 1;
            }
        }
    }
}

impl Pattern {
    /// Finds the leftmost (longest) match. Returns (start, inclusive end).
    pub fn find(&self, text: &str, from: usize) -> Option<(usize, usize)> {
        let mut start = from;
        while start < text.len() {
            check_boundary(text, start, "src/pattern.rs:216:53");
            if let Some(end) = longest(&self.frags, text, start) {
                let incl = if end > start { end - 1 } else { start };
                return Some((start, incl));
            }
            start += 1;
        }
        None
    }

    pub fn is_match(&self, text: &str) -> bool {
        if text.is_empty() {
            return false;
        }
        match longest(&self.frags, text, 0) {
            Some(end) => {
                let incl = if end > 0 { end - 1 } else { 0 };
                incl == text.len() - 1
            }
            None => false,
        }
    }

    pub fn contains_match(&self, text: &str) -> bool {
        self.find(text, 0).is_some()
    }

    pub fn replace(&self, text: &str, rep: &str, global: bool) -> String {
        let mut out = String::new();
        let mut pos = 0;
        loop {
            match self.find(text, pos) {
                Some((s, e)) => {
                    out.push_str(&text[pos..s]);
                    out.push_str(rep);
                    pos = e + 1;
                    if !global {
                        break;
                    }
                }
                None => break,
            }
        }
        if pos < text.len() {
            check_boundary(text, pos, "src/pattern.rs:257:35");
            out.push_str(&text[pos..]);
        }
        out
    }
}
