                                }
                                while ed.cursor < ed.buf.len() && ed.buf[ed.cursor] != ' ' {
                                    ed.cursor += 1;
                                }
                            }
                            "1;3D" | "1;5D" => {
                                while ed.cursor > 0 && ed.buf[ed.cursor - 1] == ' ' {
