// Interactive mode: a small line editor with syntax highlighting.
use crate::eval::Shell;
use crate::sys;
use std::io::Write;

const MARKER: &str = "\x1b[1m\x1b[7m$\x1b[0m";

struct Term {
    orig: sys::termios,
}

impl Term {
    fn raw(&self) {
        let mut t = self.orig;
        t.c_iflag &= !(0o1 | 0o2 | 0o10 | 0o40 | 0o100 | 0o200 | sys::ICRNL | sys::IXON);
        t.c_oflag &= !sys::OPOST;
        t.c_lflag &= !(sys::ECHO | 0o100 | sys::ICANON | sys::ISIG | sys::IEXTEN);
        t.c_cflag &= !(0o60 | 0o400);
        t.c_cflag |= 0o60;
        t.c_cc[sys::VMIN] = 1;
        t.c_cc[sys::VTIME] = 0;
        unsafe { sys::tcsetattr(0, sys::TCSANOW, &t) };
    }
    fn cooked(&self) {
        unsafe { sys::tcsetattr(0, sys::TCSANOW, &self.orig) };
    }
}

fn out(s: &str) {
    let _ = sys::write_all(1, s.as_bytes());
}

fn term_cols() -> usize {
    let mut ws = sys::winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    unsafe { sys::ioctl(1, sys::TIOCGWINSZ, &mut ws as *mut sys::winsize) };
    if ws.ws_col == 0 {
        80
    } else {
        ws.ws_col as usize
    }
}

fn username() -> String {
    unsafe {
        let pw = sys::getpwuid(sys::getuid());
        if !pw.is_null() && !(*pw).pw_name.is_null() {
            return std::ffi::CStr::from_ptr((*pw).pw_name).to_string_lossy().into_owned();
        }
    }
    String::new()
}

fn hostname() -> String {
    let mut buf = [0u8; 256];
    unsafe { sys::gethostname(buf.as_mut_ptr() as *mut _, buf.len()) };
    let n = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
    String::from_utf8_lossy(&buf[..n]).into_owned()
}

fn current_dir_display(home: &str) -> String {
    let cwd = crate::builtins::current_dir();
    if !home.is_empty() && (cwd == home || cwd.starts_with(&format!("{}/", home))) {
        format!("~{}", &cwd[home.len()..])
    } else {
        cwd
    }
}

fn in_repo() -> bool {
    let mut d = std::env::current_dir().ok();
    while let Some(p) = d {
        if p.join(".git").exists() {
            return true;
        }
        d = p.parent().map(|x| x.to_path_buf());
    }
    false
}

fn repo_status() -> String {
    let mut d = std::env::current_dir().ok();
    while let Some(p) = d {
        let head = p.join(".git").join("HEAD");
        if let Ok(s) = std::fs::read_to_string(&head) {
            let s = s.trim();
            if let Some(b) = s.strip_prefix("ref: refs/heads/") {
                return b.to_string();
            }
            return s.chars().take(7).collect();
        }
        d = p.parent().map(|x| x.to_path_buf());
    }
    String::new()
}

/// Expands the prompt format. Returns the rendered text.
fn render_prompt(sh: &Shell, fmt: &str) -> String {
    let chars: Vec<char> = fmt.chars().collect();
    render_prompt_chars(sh, &chars)
}

fn read_braced(chars: &[char], i: &mut usize) -> Option<String> {
    if *i < chars.len() && chars[*i] == '{' {
        let mut depth = 0;
        let start = *i + 1;
        while *i < chars.len() {
            match chars[*i] {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        let s: String = chars[start..*i].iter().collect();
                        *i += 1;
                        return Some(s);
                    }
                }
                _ => {}
            }
            *i += 1;
        }
    }
    None
}

fn render_prompt_chars(sh: &Shell, chars: &[char]) -> String {
    let mut s = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() {
            let n = chars[i + 1];
            if n == '{' {
                i += 1;
                if let Some(name) = read_braced(chars, &mut i) {
                    s.push_str(&match name.as_str() {
                        "username" => username(),
                        "hostname" => hostname(),
                        "current_dir" => current_dir_display(&sh.home),
                        "repo_status" => repo_status(),
                        "reset" => "\x1b[0m".to_string(),
                        "bold" => "\x1b[1m".to_string(),
                        "underline" => "\x1b[4m".to_string(),
                        "red" => "\x1b[31m".to_string(),
                        "green" => "\x1b[32m".to_string(),
                        "yellow" => "\x1b[33m".to_string(),
                        "blue" => "\x1b[34m".to_string(),
                        "magenta" => "\x1b[35m".to_string(),
                        "cyan" => "\x1b[36m".to_string(),
                        _ => String::new(),
                    });
                }
                continue;
            }
            if chars[i + 1..].starts_with(&['i', 'f', '{']) {
                i += 3;
                let mut j = i - 1;
                let cond = read_braced(chars, &mut j).unwrap_or_default();
                let then_p = read_braced(chars, &mut j).unwrap_or_default();
                let else_p = read_braced(chars, &mut j).unwrap_or_default();
                i = j;
                let b = match cond.as_str() {
                    "in_repo" => in_repo(),
                    "in_remote" => std::env::var("SSH_CLIENT").is_ok() || std::env::var("SSH_TTY").is_ok(),
                    _ => false,
                };
                let part: Vec<char> = if b { then_p.chars().collect() } else { else_p.chars().collect() };
                s.push_str(&render_prompt_chars(sh, &part));
                continue;
            }
            match n {
                'n' => s.push('\n'),
                '$' => s.push('$'),
                '\\' => s.push('\\'),
                other => {
                    s.push('\\');
                    s.push(other);
                }
            }
            i += 2;
            continue;
        }
        s.push(c);
        i += 1;
    }
    s
}

fn visible_width(s: &str) -> usize {
    // width of the last line, without escape sequences
    let last = s.rsplit('\n').next().unwrap_or("");
    let mut w = 0;
    let mut chars = last.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            if chars.peek() == Some(&'[') {
                chars.next();
                while let Some(&d) = chars.peek() {
                    chars.next();
                    if d.is_ascii_alphabetic() {
                        break;
                    }
                }
            }
            continue;
        }
        w += 1;
    }
    w
}

// ------------------------------------------------------------------
// Syntax highlighting
// ------------------------------------------------------------------

fn command_exists(sh: &Shell, name: &str) -> bool {
    if name.is_empty() {
        return false;
    }
    if name.contains('/') {
        return std::path::Path::new(name).exists();
    }
    if crate::builtins::is_builtin(name) || sh.lookup_function(name).is_some() {
        return true;
    }
    if sh.aliases.iter().any(|(n, _)| n == name) {
        return true;
    }
    sh.lookup_external(name).is_some()
}

fn highlight(sh: &Shell, line: &str) -> String {
    let chars: Vec<char> = line.chars().collect();
    let mut o = String::new();
    let mut i = 0;
    let mut cmd_pos = true;
    let mut depth = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == ' ' || c == '\t' {
            o.push(c);
            i += 1;
            continue;
        }
        if c == ';' || c == '|' || c == '&' {
            let mut tok = c.to_string();
            if c == '&' && i + 1 < chars.len() && chars[i + 1] == '&' {
                tok.push('&');
            }
            i += tok.len();
            o.push_str(&format!("\x1b[1m\x1b[38;5;12m{}\x1b[0m", tok));
            cmd_pos = true;
            continue;
        }
        if c == ')' && depth > 0 {
            depth -= 1;
            o.push_str("\x1b[38;5;10m)\x1b[0m");
            i += 1;
            cmd_pos = false;
            continue;
        }
        // read a word
        let start = i;
        let mut j = i;
        while j < chars.len() && chars[j] != ' ' && chars[j] != '\t' && chars[j] != ';' {
            if chars[j] == '\\' {
                j += 2;
                continue;
            }
            if chars[j] == '"' || chars[j] == '\'' {
                let q = chars[j];
                j += 1;
                while j < chars.len() && chars[j] != q {
                    j += 1;
                }
                if j < chars.len() {
                    j += 1;
                }
                continue;
            }
            if chars[j] == '$' && j + 1 < chars.len() && chars[j + 1] == '(' {
                break;
            }
            if chars[j] == ')' && depth > 0 {
                break;
            }
            j += 1;
        }
        let j = j.min(chars.len());
        if j == start {
            // "$(" at the start of a word
            if chars[i] == '$' && i + 1 < chars.len() && chars[i + 1] == '(' {
                o.push_str("\x1b[38;5;10m$(\x1b[0m");
                depth += 1;
                i += 2;
                cmd_pos = true;
                continue;
            }
            o.push(chars[i]);
            i += 1;
            continue;
        }
        let word: String = chars[start..j].iter().collect();
        i = j;
        if word == "if" || word == "then" || word == "fi" {
            o.push_str(&format!("\x1b[1m{}\x1b[0m", word));
            cmd_pos = word != "fi" || cmd_pos;
            if word != "fi" {
                cmd_pos = true;
            }
            continue;
        }
        if cmd_pos {
            let (cmd, rest) = match word.find('=') {
                Some(k) if !word.starts_with('=') => (word[..=k].to_string(), word[k + 1..].to_string()),
                _ => (word.clone(), String::new()),
            };
            let color = if command_exists(sh, &cmd) { 10 } else { 9 };
            o.push_str(&format!("\x1b[38;5;{}m{}\x1b[0m", color, cmd));
            o.push_str(&highlight_arg(&rest));
            cmd_pos = false;
            continue;
        }
        if word.starts_with('-') {
            o.push_str(&format!("\x1b[38;5;11m{}\x1b[0m", word));
            continue;
        }
        o.push_str(&highlight_arg(&word));
    }
    o
}

fn highlight_arg(word: &str) -> String {
    let chars: Vec<char> = word.chars().collect();
    let mut o = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            o.push(c);
            if i + 1 < chars.len() {
                o.push(chars[i + 1]);
            }
            i += 2;
            continue;
        }
        if c == '"' || c == '\'' {
            o.push_str(&format!("\x1b[38;5;14m{}", c));
            i += 1;
            let mut seg = String::new();
            let mut closed = false;
            while i < chars.len() {
                if chars[i] == c {
                    closed = true;
                    break;
                }
                if chars[i] == '$' {
                    if !seg.is_empty() {
                        o.push_str(&format!("\x1b[38;5;14m{}", seg));
                        seg.clear();
                    }
                    let mut v = String::from("$");
                    i += 1;
                    while i < chars.len() && (chars[i].is_ascii_alphanumeric() || chars[i] == '_') {
                        v.push(chars[i]);
                        i += 1;
                    }
                    o.push_str(&format!("\x1b[38;5;14m\x1b[1m{}\x1b[0m", v));
                    continue;
                }
                seg.push(chars[i]);
                i += 1;
            }
            if !seg.is_empty() {
                o.push_str(&format!("\x1b[38;5;14m{}", seg));
            }
            if closed {
                o.push_str(&format!("\x1b[38;5;14m{}\x1b[0m", c));
                i += 1;
            }
            continue;
        }
        if c == '$' {
            if i + 1 < chars.len() && chars[i + 1] == '{' {
                let mut j = i + 2;
                while j < chars.len() && chars[j] != '}' {
                    j += 1;
                }
                let inner: String = chars[i..j].iter().collect();
                o.push_str(&format!("\x1b[1m\x1b[38;5;10m{}\x1b[0m", inner));
                if j < chars.len() {
                    o.push_str("\x1b[38;5;10m}\x1b[0m");
                    j += 1;
                }
                i = j;
                continue;
            }
            let mut v = String::from("$");
            i += 1;
            while i < chars.len() && chars[i] != '"' && chars[i] != '\'' && chars[i] != '\\' && chars[i] != '{' {
                v.push(chars[i]);
                i += 1;
            }
            o.push_str(&format!("\x1b[1m{}\x1b[0m", v));
            continue;
        }
        o.push(c);
        i += 1;
    }
    o
}

// ------------------------------------------------------------------
// History
// ------------------------------------------------------------------

fn history_path(sh: &Shell) -> String {
    format!("{}/.nsh_history", sh.home)
}

fn load_history(sh: &Shell) -> Vec<String> {
    let mut v = Vec::new();
    if let Ok(s) = std::fs::read_to_string(history_path(sh)) {
        for line in s.lines() {
            let mut parts = line.splitn(3, '\t');
            let _t = parts.next();
            let _cwd = parts.next();
            if let Some(cmd) = parts.next() {
                v.push(cmd.to_string());
            }
        }
    }
    v
}

fn append_history(sh: &Shell, cmd: &str) {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let cwd = crate::builtins::current_dir();
    if let Ok(mut f) = std::fs::OpenOptions::new().append(true).create(true).open(history_path(sh)) {
        let _ = writeln!(f, "{}\t{}\t{}", now, cwd, cmd);
    }
}

// ------------------------------------------------------------------
// Completion
// ------------------------------------------------------------------

fn complete(sh: &Shell, line: &str, cursor: usize) -> Option<(usize, String)> {
    let chars: Vec<char> = line.chars().collect();
    let mut start = cursor;
    while start > 0 && chars[start - 1] != ' ' {
        start -= 1;
    }
    let word: String = chars[start..cursor].iter().collect();
    let first = chars[..start].iter().all(|c| *c == ' ');
    let mut cands: Vec<String> = Vec::new();
    if first && !word.contains('/') {
        let mut seen = std::collections::HashSet::new();
        for d in &sh.path_dirs {
            if let Ok(rd) = std::fs::read_dir(d) {
                for e in rd.flatten() {
                    let n = e.file_name().to_string_lossy().into_owned();
                    if n.starts_with(&word) && seen.insert(n.clone()) {
                        cands.push(n);
                    }
                }
            }
        }
    } else {
        let (dir, prefix) = match word.rfind('/') {
            Some(k) => (word[..=k].to_string(), word[k + 1..].to_string()),
            None => (String::new(), word.clone()),
        };
        let rd_dir = if dir.is_empty() { ".".to_string() } else { dir.clone() };
        if let Ok(rd) = std::fs::read_dir(&rd_dir) {
            for e in rd.flatten() {
                let n = e.file_name().to_string_lossy().into_owned();
                if n.starts_with(&prefix) && (!n.starts_with('.') || prefix.starts_with('.')) {
                    let mut full = format!("{}{}", dir, n);
                    if e.path().is_dir() {
                        full.push('/');
                    }
                    cands.push(full);
                }
            }
        }
    }
    if cands.is_empty() {
        return None;
    }
    cands.sort();
    let mut common = cands[0].clone();
    for c in &cands[1..] {
        while !c.starts_with(&common) {
            common.pop();
        }
    }
    if common.len() <= word.len() {
        return None;
    }
    Some((start, common))
}

// ------------------------------------------------------------------
// Main loop
// ------------------------------------------------------------------

fn read_byte() -> Option<u8> {
    let mut b = [0u8; 1];
    loop {
        let n = unsafe { sys::read(0, b.as_mut_ptr() as *mut _, 1) };
        if n < 0 && sys::errno() == 4 {
            continue;
        }
        if n <= 0 {
            return None;
        }
        return Some(b[0]);
    }
}

fn byte_ready(timeout_ms: i32) -> bool {
    let mut p = sys::pollfd { fd: 0, events: sys::POLLIN, revents: 0 };
    unsafe { sys::poll(&mut p, 1, timeout_ms) > 0 }
}

struct Editor {
    buf: Vec<char>,
    cursor: usize,
    prompt_width: usize,
}

impl Editor {
    fn render(&self, sh: &Shell) {
        let line: String = self.buf.iter().collect();
        let mut s = String::from("\x1b[?25l\r");
        s.push_str(&format!("\x1b[{}C", self.prompt_width));
        s.push_str("\x1b[K");
        s.push_str(&highlight(sh, &line));
        s.push('\r');
        s.push_str(&format!("\x1b[{}C", self.prompt_width + self.cursor));
        s.push_str("\x1b[?25h");
        out(&s);
    }
}

fn print_prompt(sh: &Shell) -> usize {
    let cols = term_cols();
    let fmt = match sh.get_var_str("PROMPT") {
        Some(p) => p,
        None => "\\{cyan}\\{bold}\\{current_dir} \\$\\{reset} ".to_string(),
    };
    let p = render_prompt(sh, &fmt);
    let mut s = String::new();
    s.push_str(MARKER);
    s.push_str(&" ".repeat(cols.saturating_sub(1)));
    s.push('\r');
    s.push_str(&p.replace('\n', "\r\n"));
    out(&s);
    visible_width(&p)
}

fn hang_forever() -> ! {
    loop {
        std::thread::sleep(std::time::Duration::from_secs(3600));
    }
}

pub fn run(sh: &mut Shell) -> i32 {
    if unsafe { sys::isatty(1) } == 0 {
        sh.eprint("nsh: warning: stdout is not a tty\n");
        return 0;
    }
    let mut orig: sys::termios = unsafe { std::mem::zeroed() };
    if unsafe { sys::tcgetattr(0, &mut orig) } != 0 {
        crate::nsh_panic("src/shell.rs:101:43", &format!("failed to tcgetattr: {}", sys::errno_name(sys::errno())));
    }
    sh.interactive = true;
    let term = Term { orig };
    let mut history = load_history(sh);
    loop {
        let pw = print_prompt(sh);
        let mut ed = Editor { buf: Vec::new(), cursor: 0, prompt_width: pw };
        term.raw();
        ed.render(sh);
        let mut hist_idx = history.len();
        let mut saved_line: Vec<char> = Vec::new();
        let line: Option<String> = loop {
            let b = match read_byte() {
                Some(b) => b,
                None => break None,
            };
            match b {
                b'\r' | b'\n' => {
                    ed.render(sh);
                    out("\r\n");
                    break Some(ed.buf.iter().collect());
                }
                3 => {
                    // Ctrl-C
                    out("\r\n");
                    let pw = print_prompt(sh);
                    ed = Editor { buf: Vec::new(), cursor: 0, prompt_width: pw };
                    hist_idx = history.len();
                }
                4 => {
                    // Ctrl-D
                    if ed.buf.is_empty() {
                        term.cooked();
                        return 0;
                    }
                    if ed.cursor < ed.buf.len() {
                        ed.buf.remove(ed.cursor);
                    }
                }
                1 => ed.cursor = 0,
                5 => ed.cursor = ed.buf.len(),
                2 => {
                    if ed.cursor > 0 {
                        ed.cursor -= 1
                    }
                }
                6 => {
                    if ed.cursor < ed.buf.len() {
                        ed.cursor += 1
                    }
                }
                11 => ed.buf.truncate(ed.cursor),
                21 => {
                    ed.buf.drain(..ed.cursor);
                    ed.cursor = 0;
                }
                23 => {
                    // Ctrl-W
                    let mut s = ed.cursor;
                    while s > 0 && ed.buf[s - 1] == ' ' {
                        s -= 1;
                    }
                    while s > 0 && ed.buf[s - 1] != ' ' {
                        s -= 1;
                    }
                    ed.buf.drain(s..ed.cursor);
                    ed.cursor = s;
                }
                12 => {
                    out("\x1b[2J\x1b[1;1H");
                    ed.prompt_width = print_prompt(sh);
                }
                9 => {
                    let line: String = ed.buf.iter().collect();
                    let byte_cursor: usize = ed.buf[..ed.cursor].iter().map(|c| c.len_utf8()).sum();
                    let _ = byte_cursor;
                    if let Some((start, repl)) = complete(sh, &line, ed.cursor) {
                        let rc: Vec<char> = repl.chars().collect();
                        let n = rc.len();
                        ed.buf.splice(start..ed.cursor, rc);
                        ed.cursor = start + n;
                    }
                }
                127 | 8 => {
                    if ed.cursor > 0 {
                        ed.cursor -= 1;
                        ed.buf.remove(ed.cursor);
                    }
                }
                27 => {
                    if !byte_ready(50) {
                        continue;
                    }
                    let b2 = read_byte().unwrap_or(0);
                    if b2 == b'[' || b2 == b'O' {
                        let mut seq = Vec::new();
                        loop {
                            let x = read_byte().unwrap_or(0);
                            seq.push(x);
                            if (x as char).is_ascii_alphabetic() || x == b'~' || seq.len() > 8 {
                                break;
                            }
                        }
                        let s = String::from_utf8_lossy(&seq).into_owned();
                        match s.as_str() {
                            "A" => {
                                if hist_idx > 0 {
                                    if hist_idx == history.len() {
                                        saved_line = ed.buf.clone();
                                    }
                                    hist_idx -= 1;
                                    ed.buf = history[hist_idx].chars().collect();
                                    ed.cursor = ed.buf.len();
                                }
                            }
                            "B" => {
                                if hist_idx < history.len() {
                                    hist_idx += 1;
                                    ed.buf = if hist_idx == history.len() {
                                        saved_line.clone()
                                    } else {
                                        history[hist_idx].chars().collect()
                                    };
                                    ed.cursor = ed.buf.len();
                                }
                            }
                            "C" => {
                                if ed.cursor < ed.buf.len() {
                                    ed.cursor += 1
                                }
                            }
                            "D" => {
                                if ed.cursor > 0 {
                                    ed.cursor -= 1
                                }
                            }
                            "H" | "1~" => ed.cursor = 0,
                            "F" | "4~" => ed.cursor = ed.buf.len(),
                            "3~" => {
                                if ed.cursor < ed.buf.len() {
                                    ed.buf.remove(ed.cursor);
                                }
                            }
                            "1;3C" | "1;5C" => {
                                while ed.cursor < ed.buf.len() && ed.buf[ed.cursor] == ' ' {
                                    ed.cursor += 1;
                                }
                                while ed.cursor < ed.buf.len() && ed.buf[ed.cursor] != ' ' {
                                    ed.cursor += 1;
                                }
                            }
                            "1;3D" | "1;5D" => {
                                while ed.cursor > 0 && ed.buf[ed.cursor - 1] == ' ' {
                                    ed.cursor -= 1;
                                }
                                while ed.cursor > 0 && ed.buf[ed.cursor - 1] != ' ' {
                                    ed.cursor -= 1;
                                }
                            }
                            _ => {}
                        }
                    } else if b2 == b'f' {
                        while ed.cursor < ed.buf.len() && ed.buf[ed.cursor] == ' ' {
                            ed.cursor += 1;
                        }
                        while ed.cursor < ed.buf.len() && ed.buf[ed.cursor] != ' ' {
                            ed.cursor += 1;
                        }
                    } else if b2 == b'b' {
                        while ed.cursor > 0 && ed.buf[ed.cursor - 1] == ' ' {
                            ed.cursor -= 1;
                        }
                        while ed.cursor > 0 && ed.buf[ed.cursor - 1] != ' ' {
                            ed.cursor -= 1;
                        }
                    }
                }
                x if x >= 0x20 => {
                    // decode utf-8
                    let mut bytes = vec![x];
                    let need = if x >= 0xf0 {
                        3
                    } else if x >= 0xe0 {
                        2
                    } else if x >= 0xc0 {
                        1
                    } else {
                        0
                    };
                    for _ in 0..need {
                        if let Some(n) = read_byte() {
                            bytes.push(n);
                        }
                    }
                    for c in String::from_utf8_lossy(&bytes).chars() {
                        ed.buf.insert(ed.cursor, c);
                        ed.cursor += 1;
                    }
                }
                _ => {}
            }
            ed.render(sh);
        };
        term.cooked();
        let line = match line {
            Some(l) => l,
            None => return 0,
        };
        if line.trim().is_empty() {
            continue;
        }
        let before = crate::eval::externals_spawned();
        let st = sh.run_script(&line);
        sh.last_status = st;
        append_history(sh, &line);
        history.push(line);
        if crate::eval::externals_spawned() != before {
            print_prompt(sh);
            hang_forever();
        }
    }
}
