/// Full screen history search (Ctrl-R). Returns the new input line.
fn history_search(history: &[String], initial: &str) -> String {
    let mut query: Vec<char> = initial.chars().collect();
    let mut selected: usize = 0;
    loop {
        let q: String = query.iter().collect();
        let entries: Vec<&String> = history.iter().filter(|h| h.contains(&q)).collect();
        let rows = term_rows();
        let cols = term_cols();
        let nrows = rows.saturating_sub(2);
        if selected >= entries.len() && !entries.is_empty() {
            selected = entries.len() - 1;
        }
        let mut s = String::from("\\x1b[?1049h\\x1b[2J\\x1b[0m\\x1b[1;1H\\x1b[1mhistory> \\x1b[0m");
        s.push_str(&q);
        s.push_str("\\r\\n");
        for i in 0..nrows {
            if i < entries.len() {
                let e = entries[i];
                if i == selected {
                    let pad = (cols.saturating_sub(1)).saturating_sub(e.chars().count());
                    s.push_str(&format!("\\x1b[38;5;10m\\x1b[1m\\x1b[4m{}{}\\x1b[0m", e, " ".repeat(pad)));
                } else {
                    s.push_str(e);
                }
            }
            s.push_str("\\r\\n");
        }
        s.push_str("\\x1b[1m\\x1b[7m Enter: Execute, Tab: Edit, ^C: Quit \\x1b[0m");
        s.push_str(&format!("\\x1b[1;{}H", 10 + query.len()));
        out(&s);
        let b = match read_byte() {
            Some(b) => b,
            None => return q,
        };
        match b {
            b'\\r' | b'\\n' | 9 => {
                out("\\x1b[?1049l");
                return entries.get(selected).map(|e| (*e).clone()).unwrap_or(q);
            }
            3 => {
                out("\\x1b[?1049l");
                return q;
            }
            127 | 8 => {
                query.pop();
                selected = 0;
            }
            27 => {
                if byte_ready(50) {
                    let b2 = read_byte().unwrap_or(0);
                    if b2 == b'[' || b2 == b'O' {
                        let x = read_byte().unwrap_or(0);
                        match x {
                            b'A' => selected = selected.saturating_sub(1),
                            b'B' => {
                                if selected + 1 < std::cmp::min(entries.len(), nrows) {
                                    selected += 1;
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
            x if x >= 0x20 => {
                let mut bytes = vec![x];
                let need = if x >= 0xf0 { 3 } else if x >= 0xe0 { 2 } else if x >= 0xc0 { 1 } else { 0 };
                for _ in 0..need {
                    if let Some(n) = read_byte() {
                        bytes.push(n);
                    }
                }
                query.extend(String::from_utf8_lossy(&bytes).chars());
                selected = 0;
            }
            _ => {}
        }
    }
}

