import random, sys
random.seed(int(sys.argv[2]))
atoms = ['1', '2', '10', '0', 'x', 'y', '$x', '-3', '+4', '(1+2)', 'x++', 'y--', '(x)', '007', 'z', '-x', '- 2']
ops = ['+', '-', '*', '/', '<', '>', '<=', '>=', '==', '!=', '=']
def expr(d=0):
    if d > 2 or random.random() < 0.3:
        return random.choice(atoms)
    e = expr(d+1) + random.choice(['', ' ']) + random.choice(ops) + random.choice(['', ' ']) + expr(d+1)
